  const t = g.append('text').attr('class', 'mono').attr('text-anchor', 'middle').attr('dy', '0.35em').style('font-size', size + 'px').text(text);
  g.on('click', (e) => { e.stopPropagation(); onClick(g); });
  g.on('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); e.stopPropagation(); onClick(g); } });
  if (o.o != null) g.style('opacity', o.o);
