  const g = parent.append('g').attr('class', 'sl').attr('transform', `translate(${o.x},${o.y})`).attr('tabindex', 0)
    .attr('role', 'slider').attr('aria-label', o.label || 'value').attr('aria-valuemin', o.min).attr('aria-valuemax', o.max);
