  const context = ['is', 'walking', 'in', 'the'], target = 'bedroom', xOrder = ['the', 'in', 'walking', 'is'];
  const index = { the: 1, a: 4, in: 7, is: 12, house: 811, room: 1094, cat: 2305, garden: 3920, walking: 4871, kitchen: 5112, bedroom: 9318 };
