  const scoreWords = Object.keys(want).sort((p, q) => index[p] - index[q]);
  const Urow = (word) => { const r = rng(5000 + index[word]); return Array.from({ length: h }, () => r2(r() * 0.6 - 0.3)); };
  const b = {}, y = {}, ey = {}, P = {}, grad = {};
