        gsap.fromTo(N(s.after), { opacity: 0, y: s.tagY + 22 }, { opacity: 1, y: s.tagY, duration: 0.4, ease: 'power2.out', delay: 0.3 });
        m.to(D.trained, 1.8, { delay: 0.8 });
