    const ln = (g, x1, y1, x2, y2) => g.append('line').attr('class', 'axisln').style('stroke-width', 3).attr('x1', x1).attr('y1', y1).attr('x2', x2).attr('y2', y2);
    s.axes = grp(s.plot, 'k-dim', 0);
