/* Class 4 deck (2026-11-13): copied from class4-handoff/deck/slides/24-update.js; question cards, one sentence per build,
   Problem and Solved lines and cuts added; any timing change is marked where it is made. */
/* ============ 24. The update ============ */
/* Left: the three pairs with their errors; they stay for the whole slide. Right: a plane with the
   four vectors of the worked example at their true coordinates (every vector has 2 numbers).
   Steps 2 and 3 move the context vectors: a dashed line with the direction of w comes to the tip
   of c, the small step eta * error * w is drawn on it (blue, because it is a multiple of w), and
   the arrow moves by that step, leaving a faint copy at its old place. Step 4 moves w: each push
   starts as a copy of an OLD context vector, is scaled by eta * error where it lies, and is carried
   to the tip of w; the three pushes stand tip to tail and w swings to their end.
   Every number is read from SG. */
const updateG = {
  PX: 222, EX: 470, Y: [130, 216, 302], SC: 0.56, HY: 78,     // rows: centre of the pair, of the error; row middles; pair scale; header baseline
  OX: 588, AX: 657, NX: 742,                                  // step 6: old value (small), arrow, new value
  plane: { x: 840, y: 62, U: 236, xr: [-0.45, 2.6], yr: [-1.72, 1.55] },
  FX: 420, FY: 408, AY: 480, BY: 548, FY2: 494,               // the two rules and the two lines of arithmetic
  WX: 200, CX: 560, TY: 604, CW: 92, CH: 48,                  // the small tables
  LY: 440,                                                    // the loss line
  GHOST: 0.4,                                                 // opacity of an old arrow
};
const updateK = (q) => (SG.kind[q] === 'neighbor' ? 'green' : 'red');
const updateFmt = (v) => fmt2(Math.abs(v) < 0.005 ? 0 : v);
/* a given number as it is written by hand: 1, 0.5, 0.2 */
const updateShort = (v) => String(+(+v).toFixed(2)).replace('-', MINUS);
const updateTup = (v, f) => '(' + v.map(f).join(', ') + ')';

/* The pair look of slide 18 (pairsPair in 18-pairs.js, repeated so this file builds alone), with a
   scale o.sc so that three pairs fit in the left third. Strokes are thickened to stay heavy when small. */
function updatePair(parent, a, b, cx, y, o = {}) {
  const BW = 230, BH = 96, D = 150, size = 52, sc = o.sc || 1;
  const outer = grp(parent, '', o.o);
  gsap.set(outer.node(), { x: cx, y });
  const g = outer.append('g').attr('transform', `scale(${sc})`);
  const parens = [-1, 1].map((sx) => g.append('path').attr('class', 'ol k-fg').style('stroke-width', Math.max(5, 3.6 / sc))
    .attr('d', `M${sx * 288},-58Q${sx * 320},0 ${sx * 288},58`));
  const comma = stext(g, ',', 0, 34, { size: 76, mono: false });
  const mk = (word, x, k) => {
    const bx = g.append('g').attr('class', 'chip k-' + k);
    bx.append('rect').attr('class', 'box').attr('x', -BW / 2).attr('y', -BH / 2).attr('width', BW).attr('height', BH).attr('rx', 18).style('stroke-width', Math.max(4, 3 / sc));
    bx.txt = bx.append('text').attr('class', 'mono').attr('text-anchor', 'middle').attr('dy', '0.35em').style('font-size', size + 'px').text(word);
    gsap.set(bx.node(), { x, y: 0 });
    return bx;
  };
  return { g: outer, parens, comma, D, BW, BH, L: mk(a, -D, 'blue'), R: mk(b, D, o.kR || 'fg') };
}
/* a loose number, centred on (x, y) */
function updateNum(parent, str, x, y, o = {}) {
  const g = grp(parent, o.k ? 'k-' + o.k : '', o.o);
  g.txt = stext(g, str, 0, 0, { size: o.size || 34, weight: o.weight }).attr('dy', '0.35em');
  gsap.set(g.node(), { x, y });
  return g;
}
/* One line of worked arithmetic, centred on cx: numbers in the mono face, signs as TeX.
   items: { str, k, weight } or { op: TeX source }. Returns the pieces, each { g, x, y }, all hidden. */
function updateLine(parent, items, cx, y, size) {
  const gap = size * 0.45, cw = size * 0.6;
  const ps = items.map((it) => {
    const g = it.op ? tex(parent, it.op, { size: size + 6, va: 'middle', o: 0 })
      : updateNum(parent, it.str, 0, 0, { size, k: it.k, weight: it.weight, o: 0 });
    return { g, w: it.op ? g.w : it.str.length * cw };
  });
  let x = cx - (d3.sum(ps, (p) => p.w) + gap * (ps.length - 1)) / 2;
  ps.forEach((p) => { p.x = x + p.w / 2; p.y = y; place(p.g, p.x, y); x += p.w + gap; });
  return ps;
}

/* A short arrow in the plane, from tail to v. Its head keeps a readable shape when the arrow is
   only a few board units long (the kit's arrow makes the head thinner than the line there). */
function updateStub(pl, layer, o) {
  const g = layer.append('g').attr('class', 'arrow k-' + o.k).style('opacity', 0);
  const ln = g.append('path').attr('class', 'ln').style('stroke-width', o.width || 5), hd = g.append('path').attr('class', 'hd');
  const A = { g, set(v, tail) {
    const [x1, y1] = pl.px(tail), [x2, y2] = pl.px(v), dx = x2 - x1, dy = y2 - y1, L = Math.hypot(dx, dy);
    if (L < 0.5) { ln.attr('d', ''); hd.attr('d', ''); return A; }
    const ux = dx / L, uy = dy / L, h = Math.min(o.head || 16, L * 0.8), bx = x2 - ux * h, by = y2 - uy * h, wv = h * 0.5;
    ln.attr('d', L - h > 1 ? `M${x1},${y1}L${bx},${by}` : '');
    hd.attr('d', `M${x2},${y2}L${bx - uy * wv},${by + ux * wv}L${bx + uy * wv},${by - ux * wv}Z`);
    return A;
  } };
  return A;
}

scene({
  id: 'update', act: 'III · word2vec', title: 'The update',
  init(c) {
    const s = c.s, root = c.root, G = updateG, words = SG.ctx, eta = SG.eta, w = SG.w;
    const lerp = (a, b, t) => a.map((v, i) => v + (b[i] - v) * t);
    const q0 = words.find((q) => SG.kind[q] === 'neighbor'), i0 = words.indexOf(q0);
    Object.assign(s, { words, lerp, q0, i0 });

    /* ---------- left: the three pairs and their errors ---------- */
    s.bands = words.map((q, i) => root.append('rect').attr('class', 'softk k-' + updateK(q)).style('opacity', 0)
      .attr('x', 42).attr('y', G.Y[i] - 41).attr('width', 492).attr('height', 82).attr('rx', 12));
    words.forEach((q, i) => updatePair(root, SG.target, q, G.PX, G.Y[i], { kR: updateK(q), sc: G.SC }));
    s.errH = tex(root, '\\text{error}', { x: G.EX, y: G.HY, size: 34 });
    s.errs = words.map((q, i) => updateNum(root, updateFmt(SG.err[q]), G.EX, G.Y[i], { size: 34, weight: 700 }));

    /* ---------- right: the plane ---------- */
    const P = G.plane;
    const pl = s.pl = new Plane(root, { x: P.x, y: P.y, w: (P.xr[1] - P.xr[0]) * P.U, h: (P.yr[1] - P.yr[0]) * P.U, xr: P.xr, yr: P.yr, step: 1, o: 0 });
    stext(pl.gridG, '1', pl.sx(1), pl.sy(0) + 34, { size: 26, k: 'dim' });
    stext(pl.gridG, '1', pl.sx(0) - 16, pl.sy(1), { size: 26, k: 'dim', anchor: 'end' }).attr('dy', '0.35em');
    /* layers, from the back: direction lines, old arrows, the four vectors, steps of c, pushes on w */
    const layer = () => ({ layer: pl.layer.append('g'), px: (v) => pl.px(v) });
    const LR = layer(), LG = layer(), LM = layer(), LD = layer(), LP = layer();
    const stub = (L, k, v) => updateStub(pl, L.layer, { k, width: 5.5, head: 17 }).set(v, v);

    s.vec = { w: { a: w, b: SG.wNew, k: 'blue', tex: 'w', size: 46, ld: 44 } };
    const lo = { neighbor: [4, -44], noise: [[40, 46], [72, 30]] };   // where the name stands from the tip, clear of the grid lines
    let nNoise = 0;
    words.forEach((q) => {
      s.vec[q] = { a: SG.c[q], b: SG.cNew[q], k: updateK(q), tex: `c_{\\text{${q}}}`, size: 40,
        lo: SG.kind[q] === 'neighbor' ? lo.neighbor : lo.noise[nNoise++ % 2] };
    });
    s.keys = ['w'].concat(words);
    s.ghost = {}; s.arrow = {};
    s.keys.forEach((key) => {
      const V = s.vec[key];
      s.ghost[key] = new PVec(LG, V.a, { k: V.k, width: 6, head: 20, o: 0 });
      s.arrow[key] = new PVec(LM, V.a, { k: V.k, width: 8, head: 24, tex: V.tex, size: V.size, lo: V.lo, ld: V.ld, o: 0 });
    });

    /* the step of each context vector: a dashed line with the direction of w, and eta * error * w on it */
    s.rail = {}; s.disp = {}; s.push = {};
    words.forEach((q) => {
      const V = s.vec[q], r0 = SG.err[q] > 0 ? -0.12 : -0.45, r1 = r0 + 0.6;
      const seg = (base, u0, u1) => [u0, u1].map((u) => pl.px([base[0] + u * w[0], base[1] + u * w[1]]));
      const ln = LR.layer.append('line').attr('class', 'ol k-blue').style('stroke-width', 3).style('stroke-dasharray', '9 8').style('opacity', 0);
      const from = seg([0, 0], 0.2, 0.8), to = seg(V.a, r0, r1);   // it starts on w and ends through the tip of c
      const R = s.rail[q] = { ln, set(t) {
        const p = from.map((pt, j) => lerp(pt, to[j], t));
        ln.attr('x1', p[0][0]).attr('y1', p[0][1]).attr('x2', p[1][0]).attr('y2', p[1][1]);
      } };
      R.set(0);
      s.disp[q] = stub(LD, 'blue', V.a);
      s.push[q] = stub(LP, V.k, V.a);
    });
    /* the pushes on w, tip to tail from the tip of the old w; each is eta * error * (old c) */
    let tip = w.slice();
    s.chain = words.map((q) => {
      const f = eta * SG.err[q], d = SG.c[q].map((v) => f * v), from = tip;
      tip = [tip[0] + d[0], tip[1] + d[1]];
      return { q, f, d, from };
    });

    /* an arrow grows out of the origin */
    s.grow = (tl, key, t) => {
      const A = s.arrow[key], v = s.vec[key].a;
      A.set([0, 0]);
      tl.set(N(A), { opacity: 1 }, t);
      tl.add(c.tween(0.6, (u) => A.set([v[0] * u, v[1] * u]), { ease: 'power2.out' }), t);
    };
    /* one context vector takes its step: the direction of w comes to its tip, the step is drawn, the arrow moves */
    s.nudge = (tl, q, t, tick) => {
      const V = s.vec[q], R = s.rail[q], D = s.disp[q], A = s.arrow[q];
      tl.to(R.ln.node(), { opacity: 0.85, duration: 0.2 }, t);
      tl.add(c.tween(0.55, (u) => R.set(u)), t + 0.1);
      tl.set(N(D), { opacity: 1 }, t + 0.7);
      tl.add(c.tween(0.4, (u) => D.set(lerp(V.a, V.b, u), V.a), { ease: 'power2.out' }), t + 0.7);
      tl.set(N(s.ghost[q]), { opacity: G.GHOST }, t + 1.2);
      tl.add(c.tween(0.9, (u) => { const v = lerp(V.a, V.b, u); A.set(v); if (tick) tick(v); }), t + 1.2);
    };

    /* ---------- the two rules and the arithmetic of the neighbor pair ---------- */
    s.fc = tex(root, 'c \\leftarrow \\class{update-c}{c} + \\class{update-eta}{\\eta} \\cdot \\text{error} \\cdot \\class{update-w}{\\kb{w}}',
      { x: G.FX, y: G.FY, size: 46, o: 0 });
    s.fw = tex(root, '\\kb{w} \\leftarrow \\kb{w} + \\eta \\sum \\text{error} \\cdot c', { x: G.FX, y: G.FY2, size: 46, o: 0 });
    /* where a symbol of the first rule stands on the board */
    const sym = (cls) => { const n = s.fc.select('.' + cls).node(), b = sbox(n || s.fc, 0); return [b.cx, b.cy]; };
    s.sym = { c: sym('update-c'), eta: sym('update-eta'), w: sym('update-w') };
    const d0 = w.map((v) => eta * SG.err[q0] * v), k0 = updateK(q0);
    s.A = updateLine(root, [
      { str: updateShort(eta) }, { op: '\\times' }, { str: updateFmt(SG.err[q0]), weight: 700 }, { op: '\\times' },
      { str: updateTup(w, updateShort), k: 'blue' }, { op: '=' }, { str: updateTup(d0, updateFmt) },
    ], G.FX, G.AY, 30);
    s.B = updateLine(root, [
      { str: updateTup(SG.c[q0], updateShort), k: k0 }, { op: '+' }, { str: updateTup(d0, updateFmt) }, { op: '=' },
      { str: updateTup(SG.cNew[q0], updateFmt), k: k0 },
    ], G.FX, G.BY, 30);

    /* ---------- step 5: small W and C (the same cells as on slide 22) and the rows that go back ---------- */
    const rnd = BG.rng(2207), rv = () => Math.round((rnd() * 3 - 1.5) * 10) / 10;
    const names = [SG.target].concat(words);
    const Wv = names.map((q, i) => (i === 0 ? w : [rv(), rv()]));
    const Cv = names.map((q, i) => (i === 0 ? [rv(), rv()] : SG.c[q]));
    const opt = (x, name, values) => ({
      x, y: G.TY, rows: 4, cols: 2, colGap: null, rowGap: 4, cw: G.CW, ch: G.CH, size: 28, fmt: updateFmt, values,
      rowLabels: names, labelSize: 28, name, nameSize: 52, hidden: true,
    });
    s.W = gridMat(root, opt(G.WX, 'W', Wv));
    s.C = gridMat(root, opt(G.CX, 'C', Cv));
    setK(s.W.parts.name, 'blue');
    /* a vector as two cells beside the label of its arrow (under it for the second context word, which is near the edge) */
    s.rows = s.keys.map((key, n) => {
      const V = s.vec[key], hw = sbox(s.arrow[key].lg, 0).w / 2, m = n ? s.C : s.W, i = n;
      const spot = (v) => {
        const p = pl.px(v), L = Math.hypot(p[0] - pl.sx(0), p[1] - pl.sy(0)) || 1;
        const off = V.lo || [((p[0] - pl.sx(0)) / L) * V.ld, ((p[1] - pl.sy(0)) / L) * V.ld];
        const cx = P.x + p[0] + off[0], cy = P.y + p[1] + off[1];
        return n === 2 ? [cx - G.CW, cy + 26] : [cx + hw + 14, cy - G.CH / 2];
      };
      const at = spot(V.b);   // the arrows have moved by the time the rows appear
      const r = gridRow(root, { x: at[0], y: at[1], cols: 2, colGap: null, cw: G.CW, ch: G.CH, size: 28, fmt: updateFmt, values: V.a, k: V.k, o: 0 });
      return Object.assign(r, { k: V.k, m, i, home: [m.x, m.y + m.rowY(i)], vNew: V.b });
    });

    /* ---------- step 6: the dot products and the loss, old value small beside the new one ---------- */
    s.hDot = tex(root, 'c\\cdot\\kb{w}', { x: G.NX, y: G.HY, size: 36, o: 0 });
    const flip = (a, b, y) => ({
      a, b, old: updateNum(root, updateFmt(a), G.NX, y, { size: 38, weight: 700, o: 0 }),
      arr: tex(root, '\\rightarrow', { x: G.AX, y, size: 30, va: 'middle', k: 'dim', o: 0 }),
      now: updateNum(root, updateFmt(a), G.NX, y, { size: 38, weight: 700, o: 0 }),
    });
    s.flips = words.map((q, i) => flip(SG.s[q], SG.sNew[q], G.Y[i]));
    s.lossLab = label(root, 'loss', { x: G.EX + 51, y: G.LY, size: 38, anchor: 'end', va: 'middle', o: 0 });
    s.lossFlip = flip(SG.L, SG.LNew, G.LY);
    /* the old value steps aside and becomes small; the new value counts up or down in its place */
    s.flip = (tl, F, t) => {
      tl.call(() => { setK(F.old, 'dim'); F.old.txt.style('font-weight', 500); }, null, t);
      tl.to(F.old.node(), { x: G.OX, duration: 0.45, ease: 'power2.inOut' }, t);
      tl.to(F.old.txt.node(), { fontSize: 28, duration: 0.45, ease: 'power2.inOut' }, t);
      tl.add(show(F.arr, 0.25), t + 0.3);
      tl.set(F.now.node(), { opacity: 1 }, t + 0.4);
      tl.add(c.tween(0.55, (u) => F.now.txt.text(updateFmt(F.a + (F.b - F.a) * u))), t + 0.4);
    };
  },
  steps: [
    { ask: 'How does one step change the vectors?' },
    { cap: 'One step updates the target\'s vector in W and the context vectors in C.',
      run(c) {
        const s = c.s, tl = c.tl();
        tl.add(show(s.pl.g, 0.6), 0);
        s.keys.forEach((key, n) => s.grow(tl, key, 0.5 + n * 0.45));
      } },
    { cap: 'The neighbor\'s vector moves toward the target\'s vector.',
      run(c) {
        const s = c.s, G = updateG, tl = c.tl(), A = s.A, B = s.B;
        /* a number leaves its symbol in the rule (the error leaves its row) and takes its place in the line */
        const fly = (p, from, t, dur = 0.5) => tl.fromTo(p.g.node(), { x: from[0], y: from[1], opacity: 0 },
          { x: p.x, y: p.y, opacity: 1, duration: dur, ease: 'power2.inOut' }, t);
        const on = (p, t) => tl.add(show(p.g, 0.2), t);
        tl.add(show(s.bands[s.i0], 0.3), 0);
        tl.add(write(s.fc, 0.9), 0);
        fly(A[0], s.sym.eta, 1.0); on(A[1], 1.3);
        fly(A[2], [G.EX, G.Y[s.i0]], 1.4, 0.6); on(A[3], 1.85);
        fly(A[4], s.sym.w, 1.9); on(A[5], 2.3);
        tl.fromTo(A[6].g.node(), { opacity: 0, y: A[6].y - 16 }, { opacity: 1, y: A[6].y, duration: 0.35, ease: 'power2.out' }, 2.4);
        /* the same step in the plane, then the new place of c */
        fly(B[0], s.sym.c, 3.6); on(B[1], 3.9);
        fly(B[2], [A[6].x, A[6].y], 3.95); on(B[3], 4.3);
        tl.set(B[4].g.node(), { opacity: 1 }, 4.4);
        s.nudge(tl, s.q0, 2.6, (v) => B[4].g.txt.text(updateTup(v, updateFmt)));
        B[4].g.txt.text(updateTup(SG.c[s.q0], updateFmt));
        tl.timeScale(1.2);
      } },
    /* timeScale 1.2: the cut at 2.5 is 2.5 / 1.2 s, between the two noise words */
    { cap: ['The noise vector of write moves away from the target\'s vector.', 'Paint has a smaller error, so its vector moves less.'], cut: [2.5 / 1.2],
      run(c) {
        const s = c.s, tl = c.tl();
        tl.add(hide([s.bands[s.i0], s.rail[s.q0].ln, s.A.map((p) => p.g), s.B.map((p) => p.g)], 0.3), 0);
        s.words.filter((q) => q !== s.q0).forEach((q, n) => {
          const t = 0.3 + n * 2.3, i = s.words.indexOf(q);
          tl.add(show(s.bands[i], 0.3), t);
          tl.add(indicate(s.errs[i], { scale: 1.25, duration: 0.25 }), t + 0.7);
          s.nudge(tl, q, t);
        });
        tl.timeScale(1.2);
      } },
    /* timeScale 1.2: the cut at 4.2 is 4.2 / 1.2 s, after the third push */
    { cap: ['The target\'s vector gets one push from each pair.', 'The three pushes are added, and the target\'s vector moves.'], cut: [4.2 / 1.2],
      run(c) {
        const s = c.s, G = updateG, tl = c.tl(), T = 1.3 + s.chain.length * 0.95 + 0.1;
        tl.add(hide([s.bands, s.words.map((q) => s.rail[q].ln), s.A.map((p) => p.g), s.B.map((p) => p.g)], 0.35), 0);
        tl.add(write(s.fw, 0.9), 0.3);
        s.chain.forEach((h, i) => {
          const t = 1.3 + i * 0.95, pu = s.push[h.q], a = SG.c[h.q];
          pu.set(a, [0, 0]);
          tl.add(show(s.bands[i], 0.25), t);
          /* a copy of the old c: it is scaled by eta * error where it lies, then carried to the tip of w */
          tl.to(N(pu), { opacity: 1, duration: 0.15 }, t);
          tl.add(c.tween(0.42, (u) => { const f = 1 + (h.f - 1) * u; pu.set([a[0] * f, a[1] * f], [0, 0]); }), t + 0.12);
          tl.add(c.tween(0.4, (u) => { const o = [h.from[0] * u, h.from[1] * u]; pu.set([o[0] + h.d[0], o[1] + h.d[1]], o); }), t + 0.54);
        });
        tl.add(hide(s.bands, 0.3), T);
        tl.set(N(s.ghost.w), { opacity: G.GHOST }, T);
        tl.add(c.tween(1.0, (u) => s.arrow.w.set(s.lerp(SG.w, SG.wNew, u))), T);
        tl.timeScale(1.2);
      } },
    { cap: 'The new numbers are written back into W and C.',
      run(c) {
        const s = c.s, tl = c.tl();
        tl.add(hide([s.words.map((q) => [s.push[q], s.disp[q]])], 0.4), 0);
        tl.add(s.W.reveal(0.8), 0);
        tl.add(s.C.reveal(0.8), 0.25);
        s.rows.forEach((r, n) => {
          /* the two numbers of an arrow change from old to new beside its name, then go into the table */
          const t = 1.1 + n * 0.1, t2 = 2.3 + n * 0.3;
          tl.add(show(r, 0.25), t);
          tl.add(r.to(r.vNew, 0.6), 1.55);
          tl.add(move(r, r.home[0], r.home[1], 0.75), t2);
          tl.call(() => { r.m.setRow(r.i, r.vNew); r.m.hiRow(r.i, true, r.k); }, null, t2 + 0.75);
          tl.set(N(r), { opacity: 0 }, t2 + 0.8);
        });
        tl.timeScale(1.15);
      } },
    { ask: 'Did the step help?' },
    /* the loss comes 0.4 s later than in the handoff deck, after the last flip; timeScale 1.15, so the cut at 3.38
       is 3.38 / 1.15 s */
    { cap: ['The neighbor pair now scores higher and the noise pairs score lower.', 'The loss of the three pairs falls as well.'], cut: [3.38 / 1.15],
      run(c) {
        const s = c.s, tl = c.tl();
        tl.add(hide([s.fc, s.fw], 0.4), 0);
        /* the errors on the board belong to the old vectors */
        tl.to(N([s.errH, s.errs]), { opacity: 0.3, duration: 0.4 }, 0);
        tl.add(write(s.hDot, 0.5), 0.2);
        s.flips.forEach((F, i) => tl.add(show(F.old, 0.3), 0.6 + i * 0.12));
        s.flips.forEach((F, i) => s.flip(tl, F, 1.4 + i * 0.5));
        tl.add(show([s.lossLab, s.lossFlip.old], 0.3), 3.4);
        s.flip(tl, s.lossFlip, 4.0);
        tl.timeScale(1.15);
      } },
  ],
});
/* Class 4 deck (2026-11-13): copied from class4-handoff/deck/slides/25-steps.js; question cards, one sentence per build,
   Problem and Solved lines and cuts added; any timing change is marked where it is made. */
/* ============ 25. From one step to one epoch ============ */
/* A pair as slide 18 draws it (pairsPair; repeated here so that this file builds alone):
   ( [left] , [right] ) centred on (cx, y), the left box blue. */
function stepsPair(parent, a, b, cx, y, o = {}) {
  const BW = 230, BH = 96, D = 150, size = 52;
  const g = grp(parent, '', o.o);
  gsap.set(g.node(), { x: cx, y });
  const parens = [-1, 1].map((sx) => g.append('path').attr('class', 'ol k-fg').style('stroke-width', 5)
    .attr('d', `M${sx * 288},-58Q${sx * 320},0 ${sx * 288},58`));
  const comma = stext(g, ',', 0, 34, { size: 76, mono: false });
  const mk = (word, x, k) => {
    const bx = g.append('g').attr('class', 'chip k-' + k);
    bx.append('rect').attr('class', 'box').attr('x', -BW / 2).attr('y', -BH / 2).attr('width', BW).attr('height', BH).attr('rx', 18).style('stroke-width', 4);
    bx.txt = bx.append('text').attr('class', 'mono').attr('text-anchor', 'middle').attr('dy', '0.35em').style('font-size', size + 'px').text(word);
    gsap.set(bx.node(), { x, y: 0 });
    return bx;
  };
  return { g, parens, comma, D, BW, BH, L: mk(a, -D, 'blue'), R: mk(b, D, o.kR || 'fg') };
}
/* One step as a small block: the three pairs of slide 18 at scale K without their words,
   one neighbor pair over two noise pairs. Centred on (x, y); b.scale(kx, ky) resizes it about its centre. */
function stepsBlock(parent, x, y, o = {}) {
  const K = 0.18, rw = 230 * K, rh = 96 * K, dx = 150 * K, pitch = 23, w = 112, h = 82;
  const g = grp(parent, '', o.o);
  gsap.set(g.node(), { x, y });
  const body = g.append('g');
  body.append('rect').attr('x', -w / 2).attr('y', -h / 2).attr('width', w).attr('height', h).attr('rx', 10)
    .style('fill', 'var(--bg)').style('stroke', 'var(--fg)').style('stroke-width', 3);
  ['green', 'red', 'red'].forEach((k, i) => [['blue', -dx], [k, dx]].forEach(([kk, cx]) => body.append('rect').attr('class', 'fillk k-' + kk)
    .attr('x', cx - rw / 2).attr('y', (i - 1) * pitch - rh / 2).attr('width', rw).attr('height', rh).attr('rx', 4)));
  const b = { g, body, x, y, K, pitch, w, h };
  b.scale = (kx, ky = kx) => { body.attr('transform', `scale(${kx},${ky})`); return b; };
  return b;
}
/* the sentence as slide 20 writes it: even gaps between the words, centred on cx.
   Returns one { t, x, w } per word: the text, its centre and its width. */
function stepsSentence(parent, words, cx, y, size, gap) {
  const ts = words.map((w) => stext(parent, w, 0, y, { size }).attr('dy', '0.35em'));
  const ws = ts.map((t, i) => {
    let w = 0;
    try { w = t.node().getComputedTextLength(); } catch (e) { w = 0; }
    return w > 1 ? w : words[i].length * size * 0.6;
  });
  let x = cx - (d3.sum(ws) + gap * (words.length - 1)) / 2;
  return ts.map((t, i) => { const mid = x + ws[i] / 2; t.attr('x', mid); x += ws[i] + gap; return { t, x: mid, w: ws[i] }; });
}

scene({
  id: 'steps', act: 'III · word2vec', title: 'From one step to one epoch',
  init(c) {
    const s = c.s, root = c.root, num = d3.format(','), cl = (v) => Math.max(0, Math.min(1, v));
    const words = SG.sentence, n = words.length, T = words.indexOf(SG.target), R = 2;   // range of context 2
    const SY = 150, FH = 90, PAD = 20, MY = SY - 79;             // sentence, frame, range marks
    const BP = 92, B0 = SY + 116;                                // blocks under a word: pitch, centre of the first one
    const PX = 800, PY = [250, 400, 550], HX = 690, HY = 400;    // the three pairs, and the block they fold into
    const TP = 12, NT = 118, SX = 92, TY = 380, TH = 46, GP = 11;   // the text as a strip: width of a word, words drawn, left end, middle, height, pitch of a pile
    const EPOCH = 4000000;
    const count = (i, len) => Math.min(R, i) + Math.min(R, len - 1 - i);   // neighbor pairs of the word at place i
    Object.assign(s, { n, T, NT, SY, count: (i) => count(i, n) });

    /* 1. the three pairs of the worked example */
    s.pw = SG.ctx.map((w) => {
      const g = grp(root);
      return { g, p: stepsPair(g, SG.target, w, 0, 0, { kR: SG.kind[w] === 'neighbor' ? 'green' : 'red' }) };
    });

    /* 2 and 3. the sentence, the frame on the target and the range on each side of it */
    s.sent = grp(root);
    const W = s.W = stepsSentence(s.sent, words, 800, SY, 52, 56);
    W.forEach((d) => d.t.style('opacity', 0));
    s.frame = s.sent.append('rect').attr('class', 'ol k-blue').attr('y', SY - FH / 2).attr('height', FH).attr('rx', 14)
      .style('stroke-width', 5).style('opacity', 0);
    s.marks = [0, 1].map(() => s.sent.append('path').attr('class', 'ol k-fg').style('stroke-width', 5).style('opacity', 0));
    const eL = (i) => W[i].x - W[i].w / 2 - 12, eR = (i) => W[i].x + W[i].w / 2 + 12;
    s.st = { p: T };
    s.paint = () => {
      const q = Math.max(0, Math.min(n - 1, s.st.p)), i = Math.min(n - 2, Math.floor(q)), f = q - i, b = Math.round(q);
      const x = W[i].x + (W[i + 1].x - W[i].x) * f, w = W[i].w + (W[i + 1].w - W[i].w) * f + 2 * PAD;
      s.frame.attr('x', x - w / 2).attr('width', w);
      W.forEach((d, k) => setK(d.t, k === b ? 'blue' : Math.abs(k - b) <= R ? 'green' : 'fg'));
      const lo = Math.max(0, b - R), hi = Math.min(n - 1, b + R);
      s.marks[0].attr('d', b > 0 ? `M${eL(lo)},${MY + 18}V${MY}H${eR(b - 1)}V${MY + 18}` : '');
      s.marks[1].attr('d', b < n - 1 ? `M${eL(b + 1)},${MY + 18}V${MY}H${eR(hi)}V${MY + 18}` : '');
    };
    s.paint();

    /* one block per neighbor pair, in a pile under its target */
    s.blk = grp(root);
    s.blocks = W.map((d, i) => d3.range(count(i, n)).map((r) => stepsBlock(s.blk, d.x, B0 + r * BP, { o: 0 })));
    const hero = s.hero = s.blocks[T][0];          // the block of step 1; it goes under cat in step 2
    gsap.set(hero.g.node(), { x: HX, y: HY });
    hero.scale(2);
    s.fold = (t) => {
      const k = 1 + (2 * hero.K - 1) * t, o = 1 - cl(t / 0.45);
      s.pw.forEach(({ g, p }, i) => {
        g.attr('transform', `translate(${PX + (HX - PX) * t},${PY[i] + (HY + (i - 1) * 2 * hero.pitch - PY[i]) * t}) scale(${k})`)
          .style('opacity', 1 - cl((t - 0.72) / 0.28));
        [p.L.txt, p.R.txt, p.comma].concat(p.parens).forEach((e) => e.style('opacity', o));
      });
      hero.g.style('opacity', cl((t - 0.55) / 0.3));
    };
    s.fold(0);

    /* the counter: "1 step", "30 steps", "about 4,000,000 steps" */
    const NS = 60, LS = 56, DW = NS * 0.6;
    s.cnt = grp(root, '', 0);
    s.cntNum = stext(s.cnt, '1', 0, 0, { size: NS, anchor: 'end' });
    s.one = label(s.cnt, 'step', { x: 18, y: 0, size: LS, anchor: 'start' });
    s.many = label(s.cnt, 'steps', { x: 18, y: 0, size: LS, anchor: 'start', o: 0 });
    s.about = label(s.cnt, 'about', { x: -num(EPOCH).length * DW - 22, y: 0, size: LS, anchor: 'end', o: 0 });
    s.setCount = (v) => {
      s.cntNum.text(num(v));
      s.one.style('opacity', v === 1 ? 1 : 0); s.many.style('opacity', v === 1 ? 0 : 1);
    };
    gsap.set(s.cnt.node(), { x: HX + 190, y: HY + 20 });
    s.cnt2 = [800 - (2 * DW + 18 + s.many.w) / 2 + 2 * DW, 735];
    const full = s.about.w + 22 + num(EPOCH).length * DW + 18 + s.many.w;
    s.cnt4 = [800 - full / 2 + s.about.w + 22 + num(EPOCH).length * DW, 650];

    /* 4. the whole text: a strip of words, of which only the first k are drawn */
    s.strip = grp(root, 'k-fg', 0);
    s.body = s.strip.append('rect').attr('x', SX).attr('y', TY - TH / 2).attr('height', TH).attr('rx', 4)
      .style('fill', 'color-mix(in srgb, var(--fg) 5%, var(--bg))').style('stroke', 'var(--fg)').style('stroke-width', 3);
    s.ticks = d3.range(1, NT).map((j) => s.strip.append('line').attr('x1', SX + j * TP).attr('x2', SX + j * TP)
      .attr('y1', TY - TH / 2 + 2).attr('y2', TY + TH / 2 - 2).style('stroke', 'var(--line)').style('stroke-width', 2));
    s.setLen = (k) => { s.body.attr('width', k * TP); s.ticks.forEach((l, j) => l.style('opacity', j + 1 < k - 0.5 ? 1 : 0)); };
    s.setLen(n);
    /* the steps of each word as a pile under it: 2, 3, 4, 4, ... 4, 3, 2 */
    const segY = (r) => TY + TH / 2 + 16 + r * GP;
    s.pile = grp(root, 'k-dim', 0);
    s.seg = [];
    d3.range(NT).forEach((j) => d3.range(count(j, NT)).forEach((r) => s.seg.push({ j, node: s.pile.append('rect').attr('class', 'fillk')
      .attr('x', SX + j * TP + 1.5).attr('y', segY(r)).attr('width', TP - 3).attr('height', 9).attr('rx', 1.5) })));
    /* the frame on the strip: the target and two words on each side */
    s.mini = grp(root, '', 0);
    const side = () => s.mini.append('rect').attr('class', 'k-green').attr('y', TY - TH / 2 - 6).attr('height', TH + 12).attr('rx', 3)
      .style('fill', 'var(--green)').style('fill-opacity', 0.3).style('stroke', 'var(--green)').style('stroke-width', 3);
    const gl = side(), gr = side(), END = SX + NT * TP;
    const mid = s.mini.append('rect').attr('class', 'fillk k-blue').attr('y', TY - TH / 2 - 9).attr('width', TP).attr('height', TH + 18).attr('rx', 2);
    /* u = 0: the frame is on the last word of the sentence; u = 1: on the last word of the text */
    s.setRun = (u, counting) => {
      const k = n - 1 + (NT - n) * u, x = SX + k * TP, last = Math.floor(k + 1e-6);
      const a = Math.max(SX, x - R * TP), b = Math.min(END, x + (R + 1) * TP);
      mid.attr('x', x);
      gl.attr('x', a).attr('width', Math.max(0, x - a));
      gr.attr('x', x + TP).attr('width', Math.max(0, b - x - TP));
      s.seg.forEach((g) => g.node.style('opacity', g.j <= last ? 1 : 0));
      if (counting) s.setCount(Math.round(s.total + (EPOCH - s.total) * u));
    };
    s.total = d3.sum(d3.range(n), (i) => count(i, n));      // 30
    s.setRun(0, false);
    s.setCount(1);
    s.epoch = brace(root, SX, END, TY - TH / 2 - 28, { dir: -1, text: 'one epoch', size: 46, k: 'fg', o: 0 });

    /* the sentence shrinks to the first nine words of the strip, and every block to one mark of a pile */
    const X0 = W[0].x - W[0].w / 2 - 28, KX = (n * TP) / (W[n - 1].x + W[n - 1].w / 2 + 28 - X0);
    s.shrink = (t) => {
      s.sent.attr('transform', `translate(${(SX - KX * X0) * t},${(TY - KX * SY) * t}) scale(${1 + (KX - 1) * t})`);
      s.blocks.forEach((col, i) => col.forEach((b, r) => {
        gsap.set(b.g.node(), { x: b.x + (SX + (i + 0.5) * TP - b.x) * t, y: b.y + (segY(r) + 4.5 - b.y) * t });
        b.scale(1 + ((TP - 3) / b.w - 1) * t, 1 + (9 / b.h - 1) * t);
      }));
    };
  },
  steps: [
    { ask: 'How many steps does a whole text give?' },
    { cap: 'One neighbor pair with its two noise pairs is one step.',
      run(c) {
        const s = c.s, tl = c.tl();
        tl.add(c.tween(1.3, s.fold), 0.7);
        tl.add(show(s.cnt, 0.5), 2.0);
      } },
    { cap: 'The target cat has four neighbor pairs, so it gives four steps.',
      run(c) {
        const s = c.s, tl = c.tl(), T = s.T, hero = s.hero;
        tl.add(show(s.W.map((d) => d.t), 0.4, { stagger: 0.05 }), 0);
        tl.add(draw([s.frame].concat(s.marks), 0.4), 0.6);
        tl.to(s.cnt.node(), { x: s.cnt2[0], y: s.cnt2[1], duration: 0.8, ease: 'power2.inOut' }, 0.2);
        tl.add(move(hero.g, hero.x, hero.y, 0.8), 1.0);
        tl.add(c.tween(0.8, (t) => hero.scale(2 - t)), 1.0);
        /* the other three neighbors each give a block of their own */
        [T - 2, T - 1, T + 1].forEach((wi, k) => {
          const b = s.blocks[T][k + 1], at = 1.8 + k * 0.4;
          /* it comes in under its own word, on the level of its place in the pile */
          tl.fromTo(b.g.node(), { x: s.W[wi].x, opacity: 0 }, { x: b.x, opacity: 1, duration: 0.55, ease: 'power2.inOut' }, at);
          tl.call(() => s.setCount(k + 2), null, at + 0.45);
        });
      } },
    { cap: 'With every word as the target in turn, these 9 words give 30 steps.',
      run(c) {
        const s = c.s, tl = c.tl(), fx = N([s.frame, s.marks]);
        let total = s.count(s.T), t = 0.45;
        /* a new pass from the first word */
        tl.to(fx, { opacity: 0, duration: 0.2 }, 0);
        tl.call(() => { s.st.p = 0; s.paint(); }, null, 0.2);
        tl.to(fx, { opacity: 1, duration: 0.2 }, 0.2);
        d3.range(s.n).forEach((i) => {
          if (i) { tl.to(s.st, { p: i, duration: 0.2, ease: 'power2.inOut', onUpdate: s.paint }, t); t += 0.2; }
          if (i === s.T) tl.add(indicate(s.blocks[i].map((b) => b.g), { scale: 1.1, duration: 0.12 }), t);
          else s.blocks[i].forEach((b, r) => {
            const v = ++total;
            tl.fromTo(b.g.node(), { opacity: 0, y: b.y - 28 }, { opacity: 1, y: b.y, duration: 0.16, ease: 'power2.out' }, t + r * 0.04);
            tl.call(() => s.setCount(v), null, t + r * 0.04 + 0.08);
          });
          t += 0.26;
        });
      } },
    /* the label of the epoch comes at 4.45 (4.3 in the handoff deck), so the cut at 4.42 falls after the count */
    { cap: ['A text of one million words gives about four million steps.', 'One pass over the whole text is one epoch.'], cut: [4.42],
      run(c) {
        const s = c.s, tl = c.tl();
        tl.add(c.tween(1.0, s.shrink), 0);
        tl.to(s.cnt.node(), { x: s.cnt4[0], y: s.cnt4[1], duration: 0.8, ease: 'power2.inOut' }, 0.2);
        tl.to(s.sent.node(), { opacity: 0, duration: 0.35, ease: 'power1.in' }, 0.6);
        tl.to(N([s.strip, s.mini]), { opacity: 1, duration: 0.35, ease: 'power1.out' }, 0.65);
        tl.to(s.pile.node(), { opacity: 1, duration: 0.25 }, 0.9);
        tl.to(s.blk.node(), { opacity: 0, duration: 0.25 }, 0.95);
        tl.add(c.tween(0.6, (u) => s.setLen(s.n + (s.NT - s.n) * u)), 1.2);
        tl.add(c.tween(2.0, (u) => s.setRun(u, true), { ease: 'power1.inOut', onComplete: () => s.setRun(1, true) }), 1.9);
        tl.add(show(s.about, 0.4), 4.0);
        tl.add(show(s.epoch, 0.5), 4.45);
      } },
  ],
});
/* Class 4 deck (2026-11-13): copied from class4-handoff/deck/slides/26-stop.js; question cards, one sentence per build,
   Problem and Solved lines and cuts added; any timing change is marked where it is made. */
/* ============ 26. Loss, epochs and when to stop ============ */
/* A pair as slide 18 draws it (pairsPair; repeated here so that this file builds alone). */
function stopPair(parent, a, b, cx, y, o = {}) {
  const BW = 230, BH = 96, D = 150, size = 52;
  const g = grp(parent, '', o.o);
  gsap.set(g.node(), { x: cx, y });
  const parens = [-1, 1].map((sx) => g.append('path').attr('class', 'ol k-fg').style('stroke-width', 5)
    .attr('d', `M${sx * 288},-58Q${sx * 320},0 ${sx * 288},58`));
  const comma = stext(g, ',', 0, 34, { size: 76, mono: false });
  const mk = (word, x, k) => {
    const bx = g.append('g').attr('class', 'chip k-' + k);
    bx.append('rect').attr('class', 'box').attr('x', -BW / 2).attr('y', -BH / 2).attr('width', BW).attr('height', BH).attr('rx', 18).style('stroke-width', 4);
    bx.txt = bx.append('text').attr('class', 'mono').attr('text-anchor', 'middle').attr('dy', '0.35em').style('font-size', size + 'px').text(word);
    gsap.set(bx.node(), { x, y: 0 });
    return bx;
  };
  return { g, parens, comma, D, BW, BH, L: mk(a, -D, 'blue'), R: mk(b, D, o.kR || 'fg') };
}
/* One step as the small block of slide 25 (stepsBlock): three pairs at scale K without their words. */
function stopBlock(parent, x, y, o = {}) {
  const K = 0.18, rw = 230 * K, rh = 96 * K, dx = 150 * K, pitch = 23, w = 112, h = 82;
  const g = grp(parent, '', o.o);
  gsap.set(g.node(), { x, y });
  g.append('rect').attr('x', -w / 2).attr('y', -h / 2).attr('width', w).attr('height', h).attr('rx', 10)
    .style('fill', 'var(--bg)').style('stroke', 'var(--fg)').style('stroke-width', 3);
  ['green', 'red', 'red'].forEach((k, i) => [['blue', -dx], [k, dx]].forEach(([kk, cx]) => g.append('rect').attr('class', 'fillk k-' + kk)
    .attr('x', cx - rw / 2).attr('y', (i - 1) * pitch - rh / 2).attr('width', rw).attr('height', rh).attr('rx', 4)));
  return { g, x, y, K, pitch, w, h };
}

scene({
  id: 'stop', act: 'III · word2vec', title: 'Loss and when to stop',
  init(c) {
    const s = c.s, root = c.root, cl = (v) => Math.max(0, Math.min(1, v));
    const NOISE = 'write';                                              // the pair of step 1: (cat, write)
    const PX = 800, PY = 170, EX = 540, LX = 1060, NY = 352, VY = 472, RY = 550;   // pair; columns of error and loss; rows: name, value, role
    const AX = 240, AY = 690, AW = 1060, XMAX = 5.5, E = 5;             // axes: origin, width, right end in epochs, epochs of training
    const NB = 44, BP = 24, BWD = 14, OUR = 11, U = 112;                // bars: how many, pitch, width, place of our step, height of a loss of 1
    /* loss of epoch e as a share of the height of the chart: a sketch, no real run behind it */
    const f = (e) => 0.08 + 0.54 * Math.exp(-(e - 1) / 1.2);

    /* the loss of every step of one epoch: ours is the true SG.L, the others are made up */
    const r = BG.rng(2600);
    const vals = d3.range(NB).map((j) => (j === OUR ? SG.L : Math.abs(j - OUR) <= 3 ? 1.3 + 0.8 * r() : 1.5 + 2.0 * r()));
    const mean = d3.mean(vals), avgY = AY - mean * U;
    const AH = (mean * U) / f(1);                                       // so that the average of step 2 is the first point of the curve
    const sx = (e) => AX + (AW * e) / XMAX, sy = (v) => AY - AH * v;
    const bx = (j) => AX + 7 + j * BP, ourX = bx(OUR) + BWD / 2, ourTop = AY - SG.L * U;
    const NUMY = ourTop - 14, ICY = NUMY - 33 - 14 - 41;                // the number over our bar, and the block over the number
    const X1 = sx(1), A0 = AX - 10, A1 = AX + AW + 10;                  // the average line runs from A0 to A1

    /* 3 and 4. the chart, drawn first so that it lies under everything */
    s.ax = grp(root, 'k-dim', 0);
    s.ax.append('line').attr('class', 'axisln').style('stroke-width', 3).attr('x1', AX).attr('x2', AX + AW).attr('y1', AY).attr('y2', AY);
    s.ax.append('line').attr('class', 'axisln').style('stroke-width', 3).attr('x1', AX).attr('x2', AX).attr('y1', AY).attr('y2', AY - AH - 8);
    d3.range(1, E + 1).forEach((e) => {
      s.ax.append('line').attr('class', 'axisln').style('stroke-width', 3).attr('x1', sx(e)).attr('x2', sx(e)).attr('y1', AY).attr('y2', AY + 12);
      stext(s.ax, String(e), sx(e), AY + 48, { size: 32, k: 'fg' });
    });
    label(s.ax, 'epochs', { x: AX + AW / 2, y: AY + 104, size: 40, k: 'fg' });
    s.sketch = label(root, 'sketch', { x: AX + AW, y: AY - AH + 8, anchor: 'end', size: 28, k: 'dim', it: true, o: 0 });
    s.stopLn = root.append('line').attr('class', 'ol k-dim').attr('x1', sx(E)).attr('x2', sx(E)).attr('y1', AY).attr('y2', AY)
      .style('stroke-width', 4).style('stroke-dasharray', '12 10').style('stroke-linecap', 'butt').style('opacity', 0);
    s.stopY = [AY, sy(0.55)];
    s.stopLab = label(root, 'stop', { x: sx(E), y: sy(0.55) - 18, size: 40, o: 0 });
    s.eta = root.append('line').attr('class', 'ol k-dim').style('stroke-width', 4).style('opacity', 0)
      .attr('x1', AX).attr('y1', sy(1)).attr('x2', sx(E)).attr('y2', AY);
    s.etaLab = tex(root, '\\eta', { x: sx(0.62) + 34, y: sy(1 - 0.62 / E) - 26, size: 64, va: 'middle', k: 'dim', o: 0 });
    s.curve = root.append('path').attr('class', 'ol k-fg').style('stroke-width', 7);
    s.dots = d3.range(1, E + 1).map((e) => root.append('circle').attr('class', 'fillk k-fg').attr('r', 11)
      .attr('cx', sx(e)).attr('cy', sy(f(e))).style('opacity', 0));
    /* u = 0: only the point of epoch 1; u = 1: the curve has reached epoch 5 */
    s.trace = (u) => {
      const e1 = 1 + (E - 1) * u, m = Math.max(2, Math.ceil(60 * u) + 1);
      s.curve.attr('d', u > 0 ? d3.line()(d3.range(m).map((i) => { const e = 1 + ((e1 - 1) * i) / (m - 1); return [sx(e), sy(f(e))]; })) : null);
      s.dots.forEach((d, i) => { if (i) d.style('opacity', e1 >= i + 1 - 1e-6 ? 1 : 0); });
    };
    s.trace(0);

    /* 2. one bar for the loss of every step of an epoch */
    s.bars = grp(root);
    s.bar = vals.map((v, j) => s.bars.append('rect').attr('x', bx(j)).attr('y', AY).attr('width', BWD).attr('height', 0).attr('rx', 2)
      .style('stroke', 'none').style('fill', j === OUR ? 'var(--fg)' : 'color-mix(in srgb, var(--dim) 45%, var(--bg))'));
    const grow = (j, p) => { const h = vals[j] * U * p; s.bar[j].attr('y', AY - h).attr('height', h); };
    s.growOur = (u) => grow(OUR, u);
    s.growRest = (u) => vals.forEach((v, j) => { if (j !== OUR) { const p = cl((u - (0.6 * j) / NB) / 0.4); grow(j, p * (2 - p)); } });
    s.avg = root.append('line').attr('class', 'ol k-fg').style('stroke-width', 5).style('opacity', 0)
      .attr('x1', A0).attr('x2', A1).attr('y1', avgY).attr('y2', avgY);
    s.avgLab = label(root, 'average', { x: A1 + 18, y: avgY, anchor: 'start', va: 'middle', size: 38, o: 0 });
    s.epoch = brace(root, bx(0), bx(NB - 1) + BWD, AY + 16, { dir: 1, text: 'one epoch', size: 38, k: 'dim', o: 0 });
    /* the bars of one epoch close up into the point of epoch 1 */
    s.squeeze = (t) => {
      const k = 1 - 0.97 * t;
      s.bars.attr('transform', `translate(${X1 * (1 - k)},0) scale(${k},1)`).style('opacity', 1 - cl((t - 0.5) / 0.4));
      s.avg.attr('x1', X1 + (A0 - X1) * (1 - t)).attr('x2', X1 + (A1 - X1) * (1 - t)).style('opacity', 1 - cl((t - 0.85) / 0.15));
      s.dots[0].style('opacity', cl((t - 0.75) / 0.2));
    };

    /* 1. one pair with its error and its loss */
    s.pw = grp(root, '', 0);
    const p = s.p = stopPair(s.pw, SG.target, NOISE, 0, 0, { kR: 'red' });
    s.block = stopBlock(root, ourX, ICY, { o: 0 });
    s.errName = label(root, 'error', { x: EX, y: NY, size: 52, o: 0 });
    s.errVal = stext(root, fmt2(SG.err[NOISE]), EX, VY, { size: 88, o: 0 });
    s.errRole = label(root, 'for updating', { x: EX, y: RY, size: 36, k: 'dim', o: 0 });
    s.lossName = label(root, 'loss', { x: LX, y: NY, size: 52, o: 0 });
    s.lossAt = [AX - 34 - s.lossName.w / 2, AY - AH / 2 + 16];            // where the word stands as the name of the axis
    s.lossG = grp(root, '', 0);
    s.lossVal = stext(s.lossG, '', 0, 0, { size: 88 });
    s.lossRole = label(root, 'for monitoring', { x: LX, y: RY, size: 36, k: 'dim', o: 0 });
    /* the pair becomes the middle row of a block, and its loss becomes the loss of the whole step */
    s.fold = (t) => {
      const o = 1 - cl(t / 0.45), v = SG.loss[NOISE] + (SG.L - SG.loss[NOISE]) * cl((t - 0.45) / 0.4);
      s.pw.attr('transform', `translate(${PX + (ourX - PX) * t},${PY + (ICY - PY) * t}) scale(${1 + (s.block.K - 1) * t})`);
      s.pw.style('opacity', s.shown ? 1 - cl((t - 0.72) / 0.28) : 0);
      [p.L.txt, p.R.txt, p.comma].concat(p.parens).forEach((e) => e.style('opacity', o));
      s.block.g.style('opacity', cl((t - 0.55) / 0.3));
      s.lossG.attr('transform', `translate(${LX + (ourX - LX) * t},${VY + (NUMY - VY) * t}) scale(${1 - 0.5 * t})`);
      s.lossVal.text(fmt2(v));
    };
    s.fold(0);
  },
  steps: [
    { ask: 'What do the error and the loss each tell us?' },
    { cap: ['The error tells each vector which way to move and how far.', 'The loss is one number that says how wrong the pair is.'], cut: [1.8],
      run(c) {
        const s = c.s, tl = c.tl();
        s.shown = true;
        tl.add(show(s.pw, 0.5), 0);
        tl.add(write(s.errName, 0.5), 0.6);
        tl.add(show(s.errVal, 0.4), 0.9);
        tl.add(show(s.errRole, 0.4), 1.3);
        tl.add(write(s.lossName, 0.5), 1.9);
        tl.add(show(s.lossG, 0.4), 2.2);
        tl.add(show(s.lossRole, 0.4), 2.6);
      } },
    { cap: 'The loss of an epoch is the average over all its steps.',
      run(c) {
        const s = c.s, tl = c.tl();
        tl.add(hide([s.errName, s.errVal, s.errRole, s.lossRole], 0.3), 0);
        tl.add(c.tween(1.1, s.fold), 0.2);
        tl.add(move(s.lossName, s.lossAt[0], s.lossAt[1], 0.9), 0.3);
        tl.add(c.tween(0.45, s.growOur, { ease: 'power2.out' }), 1.3);
        tl.add(c.tween(1.0, s.growRest, { ease: 'none' }), 1.8);
        tl.add(show(s.epoch, 0.4), 2.6);
        tl.add(draw(s.avg, 0.6), 3.0);
        tl.add(show(s.avgLab, 0.4), 3.5);
      } },
    { cap: 'The loss falls from one epoch to the next.',
      run(c) {
        const s = c.s, tl = c.tl();
        tl.add(hide([s.block, s.lossG, s.epoch, s.avgLab], 0.3), 0);
        tl.add(c.tween(1.0, s.squeeze), 0.25);
        tl.add(show(s.ax, 0.5), 0.9);
        tl.add(c.tween(1.3, s.trace, { ease: 'power1.inOut' }), 1.5);
        tl.add(show(s.sketch, 0.3), 2.8);
      } },
    { ask: 'When should word2vec stop training?' },
    { cap: ['Unlike Bengio, word2vec runs a fixed number of epochs, often 5.', 'The step size η shrinks to zero by the end of training.'], cut: [1.0],
      run(c) {
        const s = c.s, tl = c.tl();
        tl.add(show(s.stopLn, 0.2), 0);
        tl.fromTo(s.stopLn.node(), { attr: { y2: s.stopY[0] } }, { attr: { y2: s.stopY[1] }, duration: 0.5, ease: 'power2.out' }, 0);
        tl.add(show(s.stopLab, 0.3), 0.4);
        tl.add(draw(s.eta, 1.0), 1.1);
        tl.add(write(s.etaLab, 0.5), 1.9);
      } },
  ],
});
/* Class 4 deck (2026-11-13): copied from class4-handoff/deck/slides/27-keep.js; question cards, one sentence per build,
   Problem and Solved lines and cuts added; any timing change is marked where it is made. */
/* ============ 27. What we keep ============ */
/* W after training, with the rows of film and movie (the pair of slide 1) nearly equal.
   Then the reason: each row of W is a point, and film and movie are pulled by the same rows of C. */
scene({
  id: 'keep', act: 'III · word2vec', title: 'What we keep',
  init(c) {
    const s = c.s, root = c.root, cl = (v) => Math.max(0, Math.min(1, v));
    const words = ['river', 'film', 'movie', 'rice'], LIT = [1, 2];
    const CW = 130, CH = 80, WX = 560, WY = 300, DX = 28;        // cells of W, its corner, gap between a point and its word
    /* illustrative cells: film and movie agree to within 0.03 in every column, river and rice agree with nothing */
    const vals = [[-0.72, 0.45, -0.58, 0.09], [0.61, -0.34, 0.12, 0.83], [0.58, -0.31, 0.15, 0.80], [0.14, 0.71, -0.66, -0.92]];

    const W = s.W = gridMat(root, {
      x: WX, y: WY, rows: 4, cols: 4, rowGap: 4, cw: CW, ch: CH, size: 34, values: vals,
      rowLabels: words, labelSize: 40, name: 'W', colsText: '300 columns', markSize: 36, hidden: true,
    });
    setK(W.parts.name, 'blue');
    s.LIT = LIT;

    /* 2. the picture: where each point starts and where it ends */
    const at = { river: [260, 240], film: [640, 320], movie: [600, 640], rice: [300, 745] };   // top to bottom as in W, so no two rows cross on the way
    const end = { film: [1095, 425], movie: [1110, 495] };
    const ctx = [['watch', 1290, 240], ['cinema', 1370, 460], ['actor', 1290, 680]];

    /* the lines that pull, under the points */
    s.lines = ['film', 'movie'].map((w) => ctx.map(([, x, y]) => ({ w, x, y, node: root.append('line').attr('class', 'ol k-dim').style('stroke-width', 4) })));
    s.pos = { film: at.film.slice(), movie: at.movie.slice() };
    s.reach = 0;                                                  // 0: no line yet; 1: every line has reached its row of C
    s.link = () => s.lines.forEach((set) => set.forEach((l) => {
      const [x, y] = s.pos[l.w];
      l.node.attr('x1', x).attr('y1', y).attr('x2', x + (l.x - x) * s.reach).attr('y2', y + (l.y - y) * s.reach).style('opacity', s.reach > 0 ? 1 : 0);
    }));
    s.link();

    /* every row of W leaves the grid and closes up into one point; its word goes with it */
    s.pts = words.map((w, i) => {
      const lit = LIT.includes(i), cy = WY + W.rowY(i) + CH / 2;
      const holder = grp(root, '', 0);
      const row = W.pullRow(i, { into: holder, label: null, k: lit ? 'blue' : 'fg' });
      row.rowG.classed('hot', lit);
      const g = grp(root, 'k-' + (lit ? 'blue' : 'fg'), 0);
      const dot = g.append('circle').attr('class', 'fillk').attr('r', lit ? 16 : 12).style('opacity', 0);
      stext(g, w, -DX, 0, { size: 40, anchor: 'end' }).attr('dy', '0.35em');
      const p = { w, lit, holder, g, dot, from: [WX + W.labelX + DX, cy], to: at[w], c0: [WX + W.w / 2, cy] };
      gsap.set(g.node(), { x: p.from[0], y: p.from[1] });
      return p;
    });
    s.toPoints = (t) => s.pts.forEach((p) => {
      const x = p.from[0] + (p.to[0] - p.from[0]) * t, y = p.from[1] + (p.to[1] - p.from[1]) * t;
      const ax = p.c0[0] + (x - p.c0[0]) * t, ay = p.c0[1] + (y - p.c0[1]) * t;       // the middle of the row heads for the point
      gsap.set(p.g.node(), { x, y });
      p.holder.attr('transform', `translate(${ax},${ay}) scale(${1 - 0.94 * t}) translate(${-p.c0[0]},${-p.c0[1]})`)
        .style('opacity', s.out ? 1 - cl((t - 0.55) / 0.4) : 0);
      p.dot.style('opacity', cl((t - 0.5) / 0.4));
      if (!p.lit) setK(p.g, t > 0.5 ? 'dim' : 'fg');
    });
    s.toPoints(0);

    s.ctx = ctx.map(([w, x, y]) => {
      const g = grp(root, 'k-fg', 0);
      g.append('circle').attr('class', 'fillk').attr('r', 16);
      stext(g, w, DX, 0, { size: 40, anchor: 'start' }).attr('dy', '0.35em');
      gsap.set(g.node(), { x, y });
      return g;
    });
    /* what the two kinds of point stand for */
    s.key = [['blue', 'W', 92], ['fg', 'C', 146]].map(([k, m, y]) => {
      const g = grp(root, '', 0);
      g.append('circle').attr('class', 'fillk k-' + k).attr('r', 13).attr('cx', 100).attr('cy', y - 12);
      tex(g, `\\text{row of } ${m}`, { x: 128, y, size: 36, anchor: 'start' });
      return g;
    });
    /* u = 0: film and movie where they started; u = 1: side by side among the three rows of C */
    s.pull = (u) => {
      ['film', 'movie'].forEach((w) => {
        s.pos[w] = [at[w][0] + (end[w][0] - at[w][0]) * u, at[w][1] + (end[w][1] - at[w][1]) * u];
        gsap.set(s.pts[words.indexOf(w)].g.node(), { x: s.pos[w][0], y: s.pos[w][1] });
      });
      s.link();
    };
  },
  steps: [
    { ask: 'What do we keep after training?' },
    { cap: 'After training we keep W, and each row is the vector of a word.',
      run(c) {
        const s = c.s, tl = c.tl();
        tl.add(s.W.reveal(1.3), 0);
        s.LIT.forEach((i, k) => tl.call(() => s.W.hiRow(i, true, 'blue'), null, 1.6 + k * 0.4));
      } },
    { ask: 'Why do similar words get similar vectors?' },
    { cap: ['Words with the same neighbors are paired with the same vectors of C.', 'Solved: they are pulled the same way, so their rows of W end up close.'], cut: [2.7],
      run(c) {
        const s = c.s, tl = c.tl();
        /* the copies of the rows and of the words take over from the grid */
        s.out = true;
        tl.set(N(s.pts.map((p) => [p.holder, p.g])), { opacity: 1 }, 0);
        tl.set(N([s.W.parts.labels, s.W.parts.rows]), { opacity: 0 }, 0);
        tl.add(hide(s.W, 0.4), 0);
        tl.add(c.tween(1.1, s.toPoints), 0.1);
        tl.add(show(s.key[0], 0.4), 1.0);
        tl.add(show(s.ctx, 0.4, { stagger: 0.15 }), 1.3);
        tl.add(show(s.key[1], 0.4), 1.6);
        tl.add(c.tween(0.6, (u) => { s.reach = u; s.link(); }, { ease: 'power2.out' }), 2.0);
        tl.add(c.tween(1.4, s.pull), 2.8);
      } },
  ],
});
/* Class 4 deck (2026-11-13): copied from class4-handoff/deck/slides/28-cbow.js; question cards, one sentence per build,
   Problem and Solved lines and cuts added; any timing change is marked where it is made. */
/* ============ 28. CBOW in brief ============ */
/* A pair drawn as slide 18 draws it (pairsPair): ( [left] , [right] ), centred on (cx, y).
   The left box is the target (blue); o.kR is the colour role of the right box. */
function cbowPair(parent, a, b, cx, y, o = {}) {
  const BW = 230, BH = 96, D = 150, size = 52;
  const g = grp(parent, '', o.o);
  gsap.set(g.node(), { x: cx, y });
  const parens = [-1, 1].map((sx) => g.append('path').attr('class', 'ol k-fg').style('stroke-width', 5)
    .attr('d', `M${sx * 288},-58Q${sx * 320},0 ${sx * 288},58`));
  const comma = stext(g, ',', 0, 34, { size: 76, mono: false });
  const mk = (word, x, k) => {
    const bx = g.append('g').attr('class', 'chip k-' + k);
    bx.append('rect').attr('class', 'box').attr('x', -BW / 2).attr('y', -BH / 2).attr('width', BW).attr('height', BH).attr('rx', 18).style('stroke-width', 4);
    bx.txt = bx.append('text').attr('class', 'mono').attr('text-anchor', 'middle').attr('dy', '0.35em').style('font-size', size + 'px').text(word);
    gsap.set(bx.node(), { x, y: 0 });
    return bx;
  };
  return { g, parens, comma, cx, y, D, BW, BH, L: mk(a, -D, 'blue'), R: mk(b, D, o.kR || 'fg') };
}
/* the sentence as slide 20 writes it: even gaps between the words, centred on cx.
   Returns one { t, x, w } per word: the text, its centre and its width. */
function cbowSentence(parent, words, cx, y, size, gap) {
  const ts = words.map((w) => stext(parent, w, 0, y, { size }).attr('dy', '0.35em'));
  const ws = ts.map((t, i) => {
    let w = 0;
    try { w = t.node().getComputedTextLength(); } catch (e) { w = 0; }
    return w > 1 ? w : words[i].length * size * 0.6;
  });
  let x = cx - (d3.sum(ws) + gap * (words.length - 1)) / 2;
  return ts.map((t, i) => { const mid = x + ws[i] / 2; t.attr('x', mid); x += ws[i] + gap; return { t, x: mid, w: ws[i] }; });
}
/* a vector drawn as a short bar of cells, centred on (x, y); vals in [0, 1] set the tint of each cell */
function cbowBar(parent, vals, x, y, o = {}) {
  const cw = o.cw || 36, H = o.h || 56, W = vals.length * cw;
  const g = grp(parent, 'k-' + (o.k || 'green'), o.o);
  vals.forEach((v, i) => g.append('rect').attr('x', -W / 2 + i * cw).attr('y', -H / 2).attr('width', cw).attr('height', H)
    .style('fill', `color-mix(in srgb, var(--k) ${Math.round(8 + 72 * v)}%, var(--bg))`)
    .style('stroke', 'var(--bg)').style('stroke-width', 2));
  g.append('rect').attr('class', 'ol').attr('x', -W / 2).attr('y', -H / 2).attr('width', W).attr('height', H).attr('rx', 3)
    .style('stroke-width', 3.5);
  gsap.set(g.node(), { x, y });
  g.w = W; g.h = H;
  return g;
}

scene({
  id: 'cbow', act: 'III · word2vec', title: 'CBOW in brief',
  init(c) {
    const s = c.s, root = c.root;
    /* the sentence, the frame, the range marks and the pairs sit where slide 20 left them */
    const SY = 265, FH = 90, PAD = 20, BY = 186, T = SG.sentence.indexOf(SG.target);
    const CX = [440, 1160], RY = [450, 595];
    const VY = 362, AY = 545;                      // y of the four vectors, and of their average
    Object.assign(s, { SY, VY, AY, T });

    const W = s.W = cbowSentence(root, SG.sentence, 800, SY, 52, 56);
    W.forEach((d) => d.t.style('opacity', 0));
    s.nb = [T - 2, T - 1, T + 1, T + 2];
    s.frame = root.append('rect').attr('class', 'ol k-blue').attr('x', W[T].x - W[T].w / 2 - PAD).attr('y', SY - FH / 2)
      .attr('width', W[T].w + 2 * PAD).attr('height', FH).attr('rx', 14).style('stroke-width', 5).style('opacity', 0);
    s.q = stext(root, '?', W[T].x, SY, { size: 52, k: 'blue', o: 0 }).attr('dy', '0.35em');

    /* range 2: one mark on each side of the target, and the term with its number */
    const eL = (i) => W[i].x - W[i].w / 2 - 12, eR = (i) => W[i].x + W[i].w / 2 + 12;
    s.marks = [[eL(T - 2), eR(T - 1)], [eL(T + 1), eR(T + 2)]].map(([a, b]) => root.append('path').attr('class', 'ol k-fg')
      .style('stroke-width', 5).style('opacity', 0).attr('d', `M${a},${BY + 18}V${BY}H${b}V${BY + 18}`));
    const lab = label(root, 'range of context', { size: 46, anchor: 'start', o: 0 });
    const NW = 76, x0 = W[T].x - (lab.w + 22 + NW) / 2;
    place(lab, x0, 142);
    s.term = lab;
    s.num = root.append('g').attr('class', 'chip k-fg').style('opacity', 0);
    s.num.append('rect').attr('class', 'box').attr('x', -NW / 2).attr('y', -NW / 2).attr('width', NW).attr('height', NW).attr('rx', 14).style('stroke-width', 4);
    s.num.append('text').attr('class', 'mono').attr('text-anchor', 'middle').attr('dy', '0.35em').style('font-size', '52px').text('2');
    gsap.set(s.num.node(), { x: x0 + lab.w + 22 + NW / 2, y: 126 });

    /* the four pairs of skip-gram: the nearer words in the first row, as on slide 20 */
    s.pairs = [[T - 1, 0, 0], [T + 1, 1, 0], [T - 2, 0, 1], [T + 2, 1, 1]].map(([wi, col, row]) =>
      cbowPair(root, SG.target, SG.sentence[wi], CX[col], RY[row], { kR: 'green', o: 0 }));

    /* one small vector under each neighbor, and their average under the middle word */
    const r = BG.rng(2800), base = [0.8, 0.2, 0.55, 0.05];   // the cells differ on average, so the average bar is not flat
    const vals = s.nb.map(() => base.map((b) => Math.max(0, Math.min(1, b + (r() - 0.5) * 0.8))));
    s.vecs = s.nb.map((wi, j) => cbowBar(root, vals[j], W[wi].x, VY, { o: 0 }));
    s.avg = cbowBar(root, d3.range(4).map((i) => d3.mean(vals, (v) => v[i])), W[T].x, AY, { o: 0 });
    s.avgLab = label(root, 'average', { x: W[T].x + s.avg.w / 2 + 26, y: AY, size: 46, anchor: 'start', va: 'middle', o: 0 });
    s.ask = arrow(root, W[T].x, AY - s.avg.h / 2 - 16, W[T].x, SY + FH / 2 + 16, { k: 'fg', width: 6, head: 24, o: 0 });
  },
  steps: [
    { ask: 'Word2vec has a second model, CBOW. How is it different?' },
    { cap: 'Skip-gram, which we studied, takes one pair of words at a time.',
      run(c) {
        const s = c.s, tl = c.tl(), W = s.W;
        W.forEach((d, i) => tl.fromTo(d.t.node(), { opacity: 0, y: 16 }, { opacity: 1, y: 0, duration: 0.4, ease: 'power2.out' }, i * 0.05));
        tl.add(draw(s.frame, 0.4), 0.7);
        tl.call(() => setK(W[s.T].t, 'blue'), null, 0.9);
        tl.add(show([s.term, s.num], 0.4), 1.1);
        tl.add(draw(s.marks, 0.5), 1.2);
        tl.call(() => s.nb.forEach((i) => setK(W[i].t, 'green')), null, 1.5);
        s.pairs.forEach((p, j) => tl.fromTo(p.g.node(), { opacity: 0, y: p.y + 18 }, { opacity: 1, y: p.y, duration: 0.45, ease: 'power2.out' }, 1.8 + j * 0.3));
      } },
    /* the middle word, the question mark and the arrow come 0.15 s later than in the handoff deck, so the cut at
       2.72 falls after the label of the average */
    { cap: ['CBOW takes the average of the vectors of all the neighbors.', 'Then it asks once which word is in the middle.'], cut: [2.72],
      run(c) {
        const s = c.s, tl = c.tl(), W = s.W, mid = W[s.T];
        tl.add(hide(s.pairs.map((p) => p.g), 0.4), 0);
        /* each neighbor shows its vector */
        s.vecs.forEach((b, j) => tl.fromTo(b.node(), { y: s.SY + 40, opacity: 0 }, { y: s.VY, opacity: 1, duration: 0.45, ease: 'power2.out' }, 0.4 + j * 0.08));
        /* the four vectors slide together and become one */
        tl.to(N(s.vecs), { x: mid.x, y: s.AY, duration: 0.9, ease: 'power2.inOut' }, 1.2);
        tl.to(s.avg.node(), { opacity: 1, duration: 0.3 }, 1.95);
        tl.to(N(s.vecs), { opacity: 0, duration: 0.3 }, 2.0);
        tl.add(write(s.avgLab, 0.5), 2.2);
        /* the middle word is hidden and asked for */
        tl.to(mid.t.node(), { opacity: 0, duration: 0.3 }, 2.75);
        tl.to(s.q.node(), { opacity: 1, duration: 0.3 }, 2.9);
        tl.add(s.ask.grow(c, 0.5), 2.95);
      } },
    { cap: 'The tables, the noise words and the update stay the same.',
      run(c) {
        const s = c.s, tl = c.tl();
        tl.to(s.q.node(), { opacity: 0, duration: 0.3 }, 0);
        tl.to(s.W[s.T].t.node(), { opacity: 1, duration: 0.4 }, 0.25);
      } },
    { cap: 'CBOW is faster, and skip-gram is better for rare words.' },
  ],
});
/* Class 4 deck (2026-11-13): copied from class4-handoff/deck/slides/29-scale.js; question cards, one sentence per build,
   Problem and Solved lines and cuts added; any timing change is marked where it is made. */
/* ------------------------------------------------------------------
   Slide 29. The same idea on far more text: the three corpora to one
   scale, the cost of training, and the vectors that Google released.
   Numbers checked against their sources:
     Brown 1,181,041 words; AP News training text 13,994,528 words;
       5 epochs, about three weeks, 40 CPUs (Bengio et al. 2003, section 4)
     Google News: about 100 billion words; 300-dimensional vectors for
       3 million words and phrases; the file GoogleNews-vectors-negative300.bin.gz
       (word2vec project page, code.google.com/archive/p/word2vec)
     "an optimized single-machine implementation can train on more than
       100 billion words in one day" (Mikolov et al. 2013, arXiv 1310.4546, section 1)
------------------------------------------------------------------ */
/* the name of a corpus and its number of words on one line; the group is placed at (x, y) */
function scaleHead(parent, name, words, x, y) {
  const g = grp(parent, '', 0), t = label(g, name, { size: 46, anchor: 'start' });
  stext(g, words, t.w + 28, 0, { size: 36, anchor: 'start' });
  gsap.set(g.node(), { x, y });
  return g;
}
/* a bar of width w from x; a bar longer than max is cut with a torn edge */
function scaleBarPath(x, y, w, h, max) {
  if (w < 0.4) return '';
  if (w <= max) return `M${x},${y}h${w}v${h}h${-w}Z`;
  const n = 4, st = h / n, r = x + max;
  let d = `M${x},${y}H${r - 16}`;
  for (let i = 0; i < n; i++) d += `L${r},${y + st * (i + 0.5)}L${r - 16},${y + st * (i + 1)}`;
  return d + `H${x}Z`;
}
/* vertical lines that are redrawn on every frame of the zoom */
function scalePool(layer, stroke, width) {
  const pool = [];
  let n = 0;
  return {
    begin() { n = 0; },
    line(x, y1, y2, o) {
      let l = pool[n];
      if (!l) { l = layer.append('line').style('stroke', stroke).style('stroke-width', width); pool.push(l); }
      n++;
      l.attr('x1', x).attr('x2', x).attr('y1', y1).attr('y2', y2).style('opacity', o).style('display', null);
    },
    end() { for (let i = n; i < pool.length; i++) pool[i].style('display', 'none'); },
  };
}
/* n day cells of a calendar, seven to a row */
function scaleCal(parent, x, y, n, k) {
  const g = grp(parent, 'k-' + k), cells = [];
  for (let i = 0; i < n; i++) {
    cells.push(g.append('rect').attr('class', 'sq').attr('x', x + (i % 7) * 72).attr('y', y + Math.floor(i / 7) * 72)
      .attr('width', 64).attr('height', 64).attr('rx', 8).style('stroke', 'var(--dim)').style('stroke-width', 2).style('transition', 'none').style('opacity', 0));
  }
  return { g, cells, fill(m) { cells.forEach((r, i) => r.classed('lit', i < m)); } };
}
/* one processor */
function scaleCpu(parent, x, y) {
  const g = grp(parent, '', 0);
  g.append('rect').attr('class', 'softk').attr('x', x).attr('y', y).attr('width', 42).attr('height', 42).attr('rx', 7);
  g.append('rect').attr('class', 'fillk').attr('x', x + 13).attr('y', y + 13).attr('width', 16).attr('height', 16).attr('rx', 2);
  return g;
}
/* one computer */
function scaleMachine(parent, x, y) {
  const g = grp(parent, '', 0);
  g.append('rect').attr('class', 'softk').style('stroke-width', 4).attr('x', x).attr('y', y).attr('width', 150).attr('height', 108).attr('rx', 12);
  [34, 62].forEach((dy) => g.append('path').attr('class', 'ol').style('stroke', 'var(--k)').style('stroke-width', 5).attr('d', `M${x + 24},${y + dy}H${x + 126}`));
  g.append('circle').attr('class', 'fillk').attr('cx', x + 118).attr('cy', y + 86).attr('r', 8);
  return g;
}

scene({
  id: 'scale', act: 'IV · Why it mattered', title: 'Thousands of times more text',
  init(c) {
    const s = c.s, root = c.root;
    const X0 = 100, MAXW = 1460, BH = 76;
    const corp = [
      { name: 'Brown', words: 1181041, text: '1.2 million words', k: 'blue', y: 175 },
      { name: 'AP News', words: 13994528, text: '14 million words', k: 'blue', y: 415 },
      { name: 'Google News', words: 100e9, text: '100 billion words', k: 'yellow', y: 655 },
    ];
    /* board units per word: Google News fits on the board, then AP News is seen, then Brown */
    s.k0 = 1360 / corp[2].words; s.k1 = 130 / corp[1].words; s.k2 = 760 / corp[1].words;

    /* 1. three bars on one scale */
    s.pic = grp(root, '');
    s.grid = grp(s.pic, '', 0);
    const top = corp[0].y + 14, bot = corp[2].y + 26 + BH + 12;
    const back = scalePool(s.grid, 'var(--line)', 2);
    const bars = grp(s.pic, '');
    corp.forEach((d) => { d.bar = bars.append('path').attr('class', 'bar k-' + d.k); });
    const ticks = scalePool(grp(s.pic, ''), 'var(--bg)', 2.5);
    s.axis = s.pic.append('line').attr('class', 'axisln').style('stroke-width', 4).attr('x1', X0).attr('x2', X0).attr('y1', top).attr('y2', bot).style('opacity', 0);
    s.heads = corp.map((d) => scaleHead(root, d.name, d.text, X0, d.y));
    /* draw the bars and the scale lines for k board units per word; u < 1 while the bars grow */
    s.view = (k, u = 1) => {
      corp.forEach((d) => { d.w = d.words * k * u; d.bar.attr('d', scaleBarPath(X0, d.y + 26, d.w, BH, MAXW)); });
      back.begin(); ticks.begin();
      for (let dec = 5; dec <= 11; dec++) {
        const sp = Math.pow(10, dec) * k;
        if (sp < 22) continue;
        const a = Math.min(1, (sp - 22) / 60);
        for (let m = 1; m * sp <= MAXW + 0.5; m++) {
          if (m % 10 === 0) continue;                    // drawn by the next power of ten
          const x = X0 + m * sp;
          back.line(x, top, bot, a);
          corp.forEach((d) => { if (m * sp < Math.min(d.w - 3, MAXW - 20)) ticks.line(x, d.y + 26, d.y + 26 + BH, a * 0.75); });
        }
      }
      back.end(); ticks.end();
    };
    s.view(s.k0, 0);

    /* 2. the cost of training: days and processors, drawn one for one */
    const LX = 100, RX = 860, HY = 150, CY = 200, PY = 470;
    Object.assign(s, { LX, RX, HY });
    s.two = grp(root, '');
    s.calL = scaleCal(s.two, LX, CY, 21, 'blue');
    s.calR = scaleCal(s.two, RX, CY, 1, 'yellow');
    const cpus = grp(s.two, 'k-blue');
    s.cpus = d3.range(40).map((i) => scaleCpu(cpus, LX + (i % 10) * (496 - 42) / 9, PY + Math.floor(i / 10) * 51));
    s.machine = scaleMachine(grp(s.two, 'k-yellow'), RX, PY);
    s.costL = label(s.two, '3 weeks, 40 CPUs', { x: LX, y: 770, size: 56, anchor: 'start', o: 0 });
    s.costR = label(s.two, '1 day, 1 machine', { x: RX, y: 770, size: 56, anchor: 'start', o: 0 });

    /* 3. the table of vectors, which becomes a file */
    const GX = 430, GY = 215, r = seedRand(2913);
    const m = s.m = gridMat(root, {
      x: GX, y: GY, rows: 4, cols: 3, cw: 104, ch: 58, size: 28,
      values: () => Math.round((r() * 2 - 1) * 100) / 100,
      rowsText: '3,000,000 rows', colsText: '300 columns', markSize: 40, hidden: true,
    });
    const file = grp(root, 'k-fg');
    gsap.set(file.node(), { x: GX, y: GY });
    const L = -40, R = m.w + 40, T = -72, B = m.h + 40, E = 56;
    s.page = file.append('path').attr('class', 'ol').style('stroke-width', 5).style('opacity', 0)
      .attr('d', `M${R - E},${T}H${L}V${B}H${R}V${T + E}Z`);
    s.ear = file.append('path').attr('class', 'ol').style('stroke-width', 5).style('opacity', 0).attr('d', `M${R - E},${T}V${T + E}H${R}`);
    const cx = GX + m.w / 2, ay = GY + B + 30;
    s.down = arrow(root, cx, ay, cx, ay + 120, { k: 'yellow', width: 12, head: 40, o: 0 });
    s.tray = root.append('path').attr('class', 'ol k-yellow').style('stroke-width', 8).style('opacity', 0)
      .attr('d', `M${cx - 96},${ay + 112}V${ay + 144}H${cx + 96}V${ay + 112}`);
    s.fname = stext(root, 'GoogleNews-vectors-negative300.bin.gz', cx, ay + 208, { size: 30, k: 'dim', o: 0 });
  },
  steps: [
    { ask: 'How much text could word2vec read?' },
    { cap: 'Bengio trained on 14 million words, and word2vec on 100 billion.',
      run(c) {
        const s = c.s, tl = c.tl();
        s.heads.forEach((h, i) => tl.add(show(h, 0.4), i * 0.25));
        tl.add(show([s.axis, s.grid], 0.4), 0.5);
        tl.add(c.tween(1.1, (u) => s.view(s.k0, u)), 0.9);
        /* the scale grows until AP News can be seen, then until Brown can be seen */
        tl.add(c.tween(1.5, (t) => s.view(s.k0 * Math.pow(s.k1 / s.k0, t))), 2.5);
        tl.add(c.tween(1.1, (t) => s.view(s.k1 * Math.pow(s.k2 / s.k1, t))), 4.4);
      } },
    { cap: 'Solved: word2vec read its text in about one day on one machine.',
      run(c) {
        const s = c.s, tl = c.tl();
        tl.add(hide([s.pic, s.heads[0]], 0.4), 0);
        tl.add(move(s.heads[1], s.LX, s.HY, 0.7), 0.3);
        tl.add(move(s.heads[2], s.RX, s.HY, 0.7), 0.3);
        tl.add(show([s.calL.cells, s.calR.cells], 0.3, { stagger: 0.015 }), 1.0);
        tl.add(show([s.cpus, s.machine], 0.25, { stagger: 0.01 }), 1.4);
        /* one cell is one day */
        tl.add(c.tween(1.5, (t) => s.calL.fill(Math.round(t * 21)), { ease: 'none' }), 2.2);
        tl.call(() => s.calR.fill(1), null, 2.2 + 1.5 / 21);
        tl.add(write(s.costR, 0.7), 2.5);
        tl.add(write(s.costL, 0.7), 3.8);
      } },
    { cap: 'Google shared the vectors of 3 million words and phrases with everyone.',
      run(c) {
        const s = c.s, m = s.m, tl = c.tl();
        tl.add(hide([s.two, s.heads[1], s.heads[2]], 0.4), 0);
        tl.add(m.reveal(1.2), 0.5);
        /* a page closes around the table and its corner folds */
        tl.add(hide(m.parts.brackets, 0.3), 2.0);
        tl.to(N(m.parts.colsMark), { y: -70, duration: 0.6, ease: 'power2.inOut' }, 2.0);
        tl.to(N(m.parts.rowsMark), { x: 46, duration: 0.6, ease: 'power2.inOut' }, 2.0);
        tl.add(draw(s.page, 0.9), 2.2);
        tl.add(draw(s.ear, 0.3), 3.0);
        tl.add(s.down.grow(c, 0.5), 3.3);
        tl.add(draw(s.tray, 0.4), 3.6);
        tl.add(show(s.fname, 0.4), 3.9);
      } },
  ],
});
/* Class 4 deck (2026-11-13): copied from class4-handoff/deck/slides/30-analogy.js; question cards, one sentence per build,
   Problem and Solved lines and cuts added; any timing change is marked where it is made. */
/* ------------------------------------------------------------------
   Slide 30. Arithmetic on words: king − man + woman ≈ queen and
   Paris − France + Italy ≈ Rome.
   Both examples are given by the authors of word2vec:
     "vector(King) - vector(Man) + vector(Woman) results in a vector that is closest
       to the vector representation of the word Queen" (arXiv 1301.3781, section 1;
       first reported in Mikolov, Yih and Zweig, NAACL 2013)
     "Paris - France + Italy = Rome" (arXiv 1301.3781, section 5)
   The positions on the plane are placed by hand so that the two parallelograms
   are exact; the board says "illustrative" once.
------------------------------------------------------------------ */
/* a word of the plane: a dot and its name on the left (side -1) or on the right (side 1); p in pixels of the plane */
function analogyWord(pl, word, p, side, u) {
  const g = grp(pl.layer, 'k-fg', 0), [x, y] = pl.px([p[0] / 100, -p[1] / 100]);
  g.append('circle').attr('class', 'fillk').attr('r', 13 * u).attr('cx', x).attr('cy', y);
  stext(g, word, x + side * 28 * u, y, { size: 48 * u, anchor: side < 0 ? 'end' : 'start' }).attr('dy', '0.35em');
  return g;
}
/* an arrow from word a to word b that stops short of both dots */
function analogyArrow(pl, a, b, u, o = {}) {
  const dx = b[0] - a[0], dy = b[1] - a[1], L = Math.hypot(dx, dy), gap = 26 * u;
  const at = (t) => [(a[0] + dx * t) / 100, -(a[1] + dy * t) / 100];
  const tail = at(gap / L), tip = at(1 - gap / L);
  const v = pl.vec(tip, Object.assign({ tail, width: 8 * u, head: 28 * u, o: 0 }, o));
  v.ends = [tail, tip];
  return v;
}
/* one line of words and signs; the parts are shown one after another */
function analogyEq(parent, parts, y) {
  const t = stext(parent, '', 800, y, { size: 58 });
  return parts.map(([str, k]) => t.append('tspan').attr('class', 'k-' + k).style('stroke', 'none').style('fill-opacity', 0).text(str).node());
}

scene({
  id: 'analogy', act: 'IV · Why it mattered', title: 'Arithmetic on words',
  init(c) {
    const s = c.s, root = c.root;
    const PX = 40, PY = 190, PW = 1520, PH = 670;          // the window on the plane
    const Z = 0.55, TX = -133, TY = 390;                   // the view after it moves back in step 3
    Object.assign(s, { Z, TX, TY });

    root.append('clipPath').attr('id', 'analogy-clip').append('rect').attr('x', PX).attr('y', PY).attr('width', PW).attr('height', PH);
    s.win = grp(root, '', 0).attr('clip-path', 'url(#analogy-clip)');
    s.world = grp(s.win, '');
    gsap.set(s.world.node(), { x: 0, y: 0, scale: 1, svgOrigin: '0 0' });
    /* one grid square is 100 pixels; the grid is larger than the window so that it still fills it in step 3 */
    const pl = s.pl = new Plane(s.world, { x: -1400, y: -1000, w: 4400, h: 2800, xr: [-14, 30], yr: [-18, 10], step: 1 });
    pl.gridG.selectAll('.axis').classed('axis', false);
    s.frame = root.append('rect').attr('x', PX).attr('y', PY).attr('width', PW).attr('height', PH)
      .style('fill', 'none').style('stroke', 'var(--line)').style('stroke-width', 3).style('opacity', 0);
    s.tag = label(root, 'illustrative', { x: PX + PW - 24, y: PY + 46, size: 28, anchor: 'end', k: 'dim', o: 0 });

    /* 1 and 2. man, woman, king, queen: an exact parallelogram */
    const A = s.A = { p: { man: [500, 780], woman: [920, 690], king: [690, 380], queen: [1110, 290] }, w: {} };
    [['man', -1], ['woman', 1], ['king', -1], ['queen', 1]].forEach(([w, side]) => { A.w[w] = analogyWord(pl, w, A.p[w], side, 1); });
    A.b1 = analogyArrow(pl, A.p.man, A.p.king, 1, { k: 'dim', width: 6 });
    A.b2 = analogyArrow(pl, A.p.woman, A.p.queen, 1, { k: 'dim', width: 6 });
    A.a1 = analogyArrow(pl, A.p.man, A.p.woman, 1);
    A.a2 = analogyArrow(pl, A.p.king, A.p.queen, 1);
    A.copy = analogyArrow(pl, A.p.man, A.p.woman, 1, { k: 'yellow' });
    s.eq1 = analogyEq(root, [['king', 'blue'], [' ' + MINUS + ' ', 'fg'], ['man', 'blue'], [' + ', 'fg'], ['woman', 'blue'], [' ≈ ', 'fg'], ['queen', 'yellow']], 130);

    /* 3. France, Paris, Italy, Rome: given in window pixels of the moved-back view, drawn 1 / Z larger */
    const far = (x, y) => [(x - TX) / Z, (y - TY) / Z], u = 1 / Z;
    const B = s.B = { p: { France: far(800, 780), Paris: far(940, 400), Italy: far(1230, 730), Rome: far(1370, 350) }, w: {} };
    [['France', -1, 'blue'], ['Paris', -1, 'blue'], ['Italy', 1, 'blue'], ['Rome', 1, 'yellow']].forEach(([w, side, k]) => {
      B.w[w] = analogyWord(pl, w, B.p[w], side, u); setK(B.w[w], k);
    });
    B.a1 = analogyArrow(pl, B.p.France, B.p.Paris, u);
    B.copy = analogyArrow(pl, B.p.France, B.p.Paris, u, { k: 'yellow' });
    B.land = analogyArrow(pl, B.p.Italy, B.p.Rome, u).ends;
    s.eq2 = analogyEq(root, [['Paris', 'blue'], [' ' + MINUS + ' ', 'fg'], ['France', 'blue'], [' + ', 'fg'], ['Italy', 'blue'], [' ≈ ', 'fg'], ['Rome', 'yellow']], 130);
  },
  steps: [
    { ask: 'What do the learned vectors know?' },
    { cap: 'After training, directions in the space carry meaning.',
      run(c) {
        const s = c.s, A = s.A, tl = c.tl();
        tl.add(show([s.win, s.frame, s.tag], 0.5), 0);
        tl.add(show([A.w.man, A.w.woman, A.w.king, A.w.queen], 0.35, { stagger: 0.2 }), 0.4);
        /* the same step takes man to woman and king to queen; the same step takes man to king and woman to queen */
        tl.add(A.a1.grow(c, 0.6), 1.4);
        tl.add(A.a2.grow(c, 0.6), 2.0);
        tl.add(A.b1.grow(c, 0.5), 2.8);
        tl.add(A.b2.grow(c, 0.5), 3.2);
      } },
    { ask: 'Man is to king as woman is to which word?' },
    { cap: ['Take king, remove man and add woman.', 'The nearest word to the result is queen.'], cut: [3.08],
      run(c) {
        const s = c.s, A = s.A, tl = c.tl();
        /* queen and the arrows that lead to it step back: it is the word we look for */
        tl.add(hide([A.b1, A.b2, A.a2], 0.4), 0);
        tl.to(N(A.w.queen), { opacity: 0.2, duration: 0.4, ease: 'power2.in' }, 0);
        tl.call(() => setK([A.w.king, A.w.man, A.w.woman], 'blue'), null, 0.5);
        tl.to(s.eq1.slice(0, 5), { fillOpacity: 1, duration: 0.35, stagger: 0.14, ease: 'power2.out' }, 0.5);
        /* a copy of the step from man to woman starts again at king */
        tl.add(show(A.copy, 0.3), 1.5);
        tl.add(A.copy.to(c, A.a2.ends[1], 1.2, {}, A.a2.ends[0]), 1.9);
        tl.call(() => setK(A.w.queen, 'yellow'), null, 3.1);
        tl.to(N(A.w.queen), { opacity: 1, duration: 0.3, ease: 'power2.out' }, 3.1);
        tl.to(s.eq1.slice(5), { fillOpacity: 1, duration: 0.35, stagger: 0.14, ease: 'power2.out' }, 3.1);
        tl.add(indicate(A.w.queen, { scale: 1.12 }), 3.4);
      } },
    { cap: 'The same works for countries and capitals.',
      run(c) {
        const s = c.s, B = s.B, tl = c.tl();
        tl.to(s.eq1, { fillOpacity: 0, duration: 0.3, ease: 'power2.in' }, 0);
        /* the view moves back: the first four words become small in a corner of a larger piece of the space */
        tl.to(s.world.node(), { x: s.TX, y: s.TY, scale: s.Z, duration: 1.0, ease: 'power2.inOut' }, 0.1);
        tl.add(show([B.w.France, B.w.Paris, B.w.Italy], 0.35, { stagger: 0.15 }), 1.1);
        tl.to(s.eq2.slice(0, 5), { fillOpacity: 1, duration: 0.35, stagger: 0.12, ease: 'power2.out' }, 1.1);
        tl.add(B.a1.grow(c, 0.5), 1.8);
        tl.add(show(B.copy, 0.3), 2.3);
        tl.add(B.copy.to(c, B.land[1], 1.0, {}, B.land[0]), 2.6);
        tl.add(show(B.w.Rome, 0.3), 3.6);
        tl.to(s.eq2.slice(5), { fillOpacity: 1, duration: 0.35, stagger: 0.14, ease: 'power2.out' }, 3.6);
        tl.add(indicate(B.w.Rome, { scale: 1.12 }), 3.9);
      } },
  ],
});
/* Class 4 deck (2026-11-13): copied from class4-handoff/deck/slides/31-transfer.js; question cards, one sentence per build,
   Problem and Solved lines and cuts added; any timing change is marked where it is made. */
/* ------------------------------------------------------------------
   Slide 31. Train once, use everywhere: three tasks that each start
   from random vectors, one table W learned from plain text, the same
   W in every task, and the models that followed.
   Years checked against the papers: word2vec 2013 (arXiv 1301.3781 and
   1310.4546), GloVe 2014 (Pennington, Socher and Manning, EMNLP 2014),
   ELMo 2018 (Peters et al., NAACL 2018), BERT 2018 (Devlin et al.,
   arXiv 1810.04805), GPT 2018 (Radford et al., OpenAI, June 2018).
------------------------------------------------------------------ */
/* rows x cols numbers in (-1, 1) with two decimals, the same on every run */
function transferVals(seed, rows, cols) {
  const r = seedRand(seed);
  return d3.range(rows).map(() => d3.range(cols).map(() => Math.round((r() * 2 - 1) * 100) / 100));
}
/* lines of grey strokes that stand for running text; the group slides to the right inside its window */
function transferText(parent, id, x, y, w, h, rows, extra) {
  const r = seedRand(4107), g = grp(parent, '', 0);
  g.append('clipPath').attr('id', id).append('rect').attr('x', x).attr('y', y).attr('width', w).attr('height', h);
  const run = g.append('g').attr('clip-path', `url(#${id})`).append('g'), pitch = h / rows;
  for (let i = 0; i < rows; i++) {
    let left = x - 40 - r() * 60;
    while (left < x + w + extra) {
      const len = 34 + r() * 96;
      run.append('rect').attr('x', left).attr('y', y + pitch * (i + 0.5) - 9).attr('width', len).attr('height', 18).attr('rx', 9)
        .style('fill', 'var(--dim)').style('fill-opacity', 0.5);
      left += len + 20;
    }
  }
  return { g, run, extra };
}

scene({
  id: 'transfer', act: 'IV · Why it mattered', title: 'Train once, use everywhere',
  init(c) {
    const s = c.s, root = c.root;
    const tasks = ['is this review good or bad', 'find the names in a sentence', 'translate'];
    const BW = 470, BH = 280, BY = 410, BX = [40, 565, 1090];
    const small = { rows: 3, cols: 3, cw: 92, ch: 46, size: 26 }, SWID = 3 * 92 + 57, big = 124 / 92;
    const WX = 520, WY = 130;
    const trained = transferVals(3101, 3, 3);
    Object.assign(s, { trained, WX, WY, big });

    /* 1. three tasks, each with its own small table */
    s.boxes = tasks.map((name, i) => {
      const g = grp(root, '', 0), x = BX[i];
      g.append('rect').attr('class', 'softk k-dim').attr('x', x).attr('y', BY).attr('width', BW).attr('height', BH).attr('rx', 16);
      label(g, name, { x: x + BW / 2, y: BY + 54, size: 32 });
      const tx = x + (BW - SWID) / 2, ty = BY + 84;
      const own = gridMat(g, Object.assign({ x: tx, y: ty, values: transferVals(500 + i, 3, 3) }, small));
      return { g, own, tx, ty, next: transferVals(600 + i, 3, 3) };
    });

    /* 2. plain text runs into one larger table W */
    s.text = transferText(root, 'transfer-clip', 50, 136, 455, 220, 5, 620);
    gsap.set(s.text.run.node(), { x: -s.text.extra });
    s.W = gridMat(root, { x: WX, y: WY, rows: 3, cols: 3, cw: 124, ch: 62, size: 34, values: transferVals(3100, 3, 3), hidden: true });
    s.name = tex(root, 'W', { x: WX + s.W.w / 2, y: WY - 26, size: 64, o: 0 });

    /* 3. three copies of W, drawn at the size of the small tables and enlarged to lie on W */
    s.copies = s.boxes.map(() => {
      const m = gridMat(root, Object.assign({ values: trained, k: 'blue', o: 0 }, small));
      gsap.set(m.g.node(), { x: WX, y: WY, scale: big, svgOrigin: '0 0' });
      return m;
    });
    s.word = label(root, 'transfer learning', { x: 1040, y: WY + s.W.h / 2, size: 56, anchor: 'start', va: 'middle', o: 0 });

    /* 4. the models that followed, in order */
    const LY = 782, stops = [['word2vec', '2013'], ['GloVe', '2014'], ['ELMo', '2018'], ['BERT and GPT', '2018']];
    s.line = arrow(root, 80, LY, 1520, LY, { width: 5, head: 26, o: 0 });
    s.stops = stops.map(([name, year], i) => {
      const g = grp(root, '', 0), x = 230 + i * 370;
      g.append('circle').attr('class', 'fillk k-fg').attr('r', 11).attr('cx', x).attr('cy', LY);
      label(g, name, { x, y: LY - 30, size: 38 });
      stext(g, year, x, LY + 52, { size: 32, k: 'dim' });
      return { g, at: (x - 80) / 1440 };
    });
  },
  steps: [
    { ask: 'Why learn word vectors only once?' },
    { cap: 'Problem: each task learned its own vectors from little labeled data.',
      run(c) {
        const s = c.s, tl = c.tl();
        s.boxes.forEach((b, i) => {
          tl.fromTo(b.g.node(), { opacity: 0, y: 20 }, { opacity: 1, y: 0, duration: 0.45, ease: 'power2.out' }, i * 0.3);
          tl.add(b.own.to(b.next, 1.5, { roll: true }), 0.6 + i * 0.3);
        });
      } },
    { cap: 'Word2vec learns the vectors once, from plain text with no labels.',
      run(c) {
        const s = c.s, tl = c.tl();
        tl.add(s.W.reveal(0.8), 0);
        tl.add(write(s.name, 0.4), 0.5);
        tl.add(show(s.text.g, 0.4), 0.6);
        tl.to(s.text.run.node(), { x: 0, duration: 2.6, ease: 'power1.out' }, 0.6);
        tl.add(s.W.to(s.trained, 2.2, { roll: true }), 0.9);
        tl.call(() => setK([s.W.g, s.name], 'blue'), null, 3.1);
      } },
    { cap: ['Solved: every task then starts from the same vectors.', 'This is called transfer learning.'], cut: [2.45],
      run(c) {
        const s = c.s, tl = c.tl();
        s.copies.forEach((m, i) => {
          const b = s.boxes[i], t = 0.1 + i * 0.7;
          tl.set(m.g.node(), { opacity: 1 }, t);
          tl.to(m.g.node(), { x: b.tx, y: b.ty, scale: 1, duration: 0.9, ease: 'power2.inOut' }, t);
          tl.add(hide(b.own, 0.3), t + 0.45);
        });
        tl.add(write(s.word, 0.9), 2.5);
      } },
    { cap: 'Later models pretrain the whole network, not only the word table.',
      run(c) {
        const s = c.s, tl = c.tl();
        tl.add(s.line.grow(c, 2.0, { ease: 'none' }), 0);
        s.stops.forEach((p) => tl.add(show(p.g, 0.4), Math.max(0, 2.0 * p.at - 0.15)));
      } },
  ],
});
/* Class 4 deck (2026-11-13): copied from class4-handoff/deck/slides/32-recap.js; question cards, one sentence per build,
   Problem and Solved lines and cuts added; any timing change is marked where it is made. */
/* ============ 32. Recap ============ */
/* A pair drawn as slide 18 draws it (pairsPair), at scale k: ( [left] , [right] ), centred on (cx, y).
   The left box is the target (blue); o.kR is the colour role of the right box. */
function recapPair(parent, a, b, cx, y, o = {}) {
  const BW = 230, BH = 96, D = 150, size = 52, k = o.scale || 1;
  const g = grp(parent, '', o.o);
  gsap.set(g.node(), { x: cx, y });
  const in_ = g.append('g').attr('transform', `scale(${k})`);
  [-1, 1].forEach((sx) => in_.append('path').attr('class', 'ol k-fg').style('stroke-width', 5)
    .attr('d', `M${sx * 288},-58Q${sx * 320},0 ${sx * 288},58`));
  stext(in_, ',', 0, 34, { size: 76, mono: false });
  const mk = (word, x, kk) => {
    const bx = in_.append('g').attr('class', 'chip k-' + kk).attr('transform', `translate(${x},0)`);
    bx.append('rect').attr('class', 'box').attr('x', -BW / 2).attr('y', -BH / 2).attr('width', BW).attr('height', BH).attr('rx', 18).style('stroke-width', 4);
    bx.append('text').attr('class', 'mono').attr('text-anchor', 'middle').attr('dy', '0.35em').style('font-size', size + 'px').text(word);
    return bx;
  };
  return { g, cx, y, w: 640 * k, L: mk(a, -D, 'blue'), R: mk(b, D, o.kR || 'fg') };
}
/* a short one-hot column as slide 1 draws it: bracketed cells, the cell with the 1 filled */
function recapCol(parent, vals, x, top, o = {}) {
  const cw = o.cw || 92, ch = o.ch || 50, H = vals.length * ch, b = 14;
  const g = parent.append('g').attr('class', 'mat k-' + (o.k || 'blue'));
  gsap.set(g.node(), { x, y: top });
  g.cells = vals.map((v, i) => {
    const cg = g.append('g').attr('transform', `translate(0,${i * ch})`).style('opacity', 0);
    cg.rect = cg.append('rect').attr('class', 'cell').attr('width', cw).attr('height', ch).style('transition', 'none');
    cg.txt = cg.append('text').attr('class', 'mono').attr('x', cw / 2).attr('y', ch / 2).attr('dy', '0.35em').attr('text-anchor', 'middle')
      .style('font-size', (o.size || 34) + 'px').text(v);
    return cg;
  });
  g.brk = [g.append('path').attr('class', 'brk').attr('d', `M${b - 6},${-5}h${-b}v${H + 10}h${b}`).style('opacity', 0),
    g.append('path').attr('class', 'brk').attr('d', `M${cw + 6 - b},${-5}h${b}v${H + 10}h${-b}`).style('opacity', 0)];
  g.hot = (i) => { g.cells[i].rect.style('fill', 'var(--k)'); g.cells[i].txt.style('fill', 'var(--bg)').style('font-weight', 700); };
  g.w = cw; g.h = H;
  return g;
}

scene({
  id: 'recap', act: 'IV · Why it mattered', title: 'Recap',
  init(c) {
    const s = c.s, root = c.root;
    const LEFT = 60, ROW = [185, 485, 775];      // common left edge of the three pictures, and the middle of each row
    s.DIM = 0.85;

    /* 1. a one-hot vector */
    s.ONE = 1;
    s.col = recapCol(root, ['0', '1', '0', '⋮', '0'], LEFT + 6, ROW[0] - 125);

    /* 2. Bengio's network, input to loss */
    s.pipe = bgPipe(root, { upto: null, cy: ROW[1], x0: LEFT + 85 });

    /* 3. one neighbor pair and two noise pairs */
    const K = 0.7, PW = 640 * K, GAP = 48;
    s.pairs = SG.ctx.map((w, i) => recapPair(root, SG.target, w, LEFT + PW / 2 + i * (PW + GAP), ROW[2],
      { scale: K, kR: SG.kind[w] === 'neighbor' ? 'green' : 'red', o: 0 }));
  },
  steps: [
    { ask: 'What did we learn today?' },
    { cap: 'A one-hot vector says nothing about meaning.',
      run(c) {
        const s = c.s, tl = c.tl();
        tl.add(draw(s.col.brk, 0.5), 0);
        tl.to(N(s.col.cells), { opacity: 1, duration: 0.35, stagger: 0.08, ease: 'power2.out' }, 0.3);
        tl.call(() => s.col.hot(s.ONE), null, 1.0);
        tl.add(indicate(s.col.cells[s.ONE], { scale: 1.12 }), 1.0);
      } },
    { cap: 'Bengio learned word vectors inside a language model.',
      run(c) {
        const s = c.s, tl = c.tl();
        tl.to(s.col.node(), { opacity: s.DIM, duration: 0.5 }, 0);
        s.pipe.order.forEach((id, i) => tl.add(s.pipe.reveal(id, 0.35), 0.3 + i * 0.17));
      } },
    { cap: 'Word2vec learns them from neighbor and noise pairs, on far more text.',
      run(c) {
        const s = c.s, tl = c.tl();
        tl.to(s.pipe.g.node(), { opacity: s.DIM, duration: 0.5 }, 0);
        s.pairs.forEach((p, i) => tl.fromTo(p.g.node(), { opacity: 0, y: p.y + 18 }, { opacity: 1, y: p.y, duration: 0.45, ease: 'power2.out' }, 0.3 + i * 0.4));
      } },
  ],
});
/* ---------- start ----------
   This file ends board.js, which the deck loads inside its last board slide: every slide is in the page
   by then and Reveal.initialize has not run yet, so the fragments are counted with the others. */
boardMount();
document.addEventListener('DOMContentLoaded', () => {
  const ready = new Promise((res) => (Reveal.isReady() ? res() : Reveal.on('ready', res)));
  const faces = ['500 30px "STIX Two Text"', '700 30px "STIX Two Text"', 'italic 500 30px "STIX Two Text"', '500 30px "JetBrains Mono"', '700 30px "JetBrains Mono"'];
  const fonts = document.fonts ? Promise.race([Promise.all(faces.map((f) => document.fonts.load(f))), new Promise((r) => setTimeout(r, 2500))]) : null;
  Promise.all([ready, MathJax.startup.promise, fonts]).then(() => {
    document.head.appendChild(MathJax.svgStylesheet());
    ['slidechanged', 'fragmentshown', 'fragmenthidden', 'overviewhidden'].forEach((e) => Reveal.on(e, boardQueue));
    Reveal.addKeyBinding({ keyCode: 80, key: 'P', description: 'Pause or resume the animation' }, () => boardPause());
    Reveal.addKeyBinding({ keyCode: 82, key: 'R', description: 'Replay this build' }, () => { if (Deck.cur) boardReplay(Deck.cur); });
    boardSync();
  }).catch((e) => console.error('[board] could not start', e));
});
